/* Lektionsinhalte – Deutsch */
I18N.registerLessons("de", {

/* ===================== KLAVIER ===================== */
"piano-1":{title:"Die Tasten kennenlernen",goal:"Jeden Ton auf dem Klavier in fünf Sekunden finden",b:{
0:"Das Klavier wirkt einschüchternd: 88 Tasten. Die Wahrheit? Es gibt nur <b>12 Tasten</b>, die sich immer wieder wiederholen. Sobald du das Muster siehst, öffnet sich das ganze Instrument.",
1:"Das Geheimnis liegt in den schwarzen Tasten: Sie sind abwechselnd in Gruppen zu <b>zwei</b> und zu <b>drei</b> angeordnet. Das ist deine Landkarte.",
2:["Suche eine Gruppe aus zwei schwarzen Tasten.","Die weiße Taste direkt links davon (Richtung tiefe Töne) ist das <b>C</b>.","Von dort geht es einfach weiter: C, D, E, F, G, A, H — und dann wieder C.","Jedes nächste C ist derselbe Klang, nur höher. Das nennt man eine <b>Oktave</b>."],
3:"Drücke die markierte Taste — das ist das C (C4). Versuche auch die anderen C zu finden.",
4:"<b>Goldener Tipp:</b> Das eingestrichene C (C4) liegt ungefähr in der Mitte des Klaviers, gegenüber dem Schloss oder dem Logo. Es ist der Ankerpunkt jedes Pianisten.",
5:"Die C-Dur-Tonleiter — die sieben weißen Töne und zurück zum C",
6:{q:"Wie findet man den Ton C auf dem Klavier?",o:["Die weiße Taste links von drei schwarzen","Die weiße Taste direkt an der Gruppe aus zwei schwarzen Tasten, auf der tiefen Seite","Die erste schwarze Taste","Die weiße Taste in der Mitte der Klaviatur"],w:"Das C ist immer die weiße Taste direkt neben der Zweiergruppe schwarzer Tasten, auf der Seite der tiefen Töne."},
7:"Setz dich ans Instrument (oder an die Bildschirmklaviatur) und sage laut alle C, danach alle F. Drei Minuten – fertig."}},

"piano-2":{title:"Die rechte Hand — fünf Finger, fünf Töne",goal:"C–D–E–F–G hintereinander spielen, ohne auf die Hände zu schauen",b:{
0:"Am Klavier hat jeder Finger eine Nummer: <b>1 = Daumen</b>, 2 = Zeigefinger, 3 = Mittelfinger, 4 = Ringfinger, 5 = kleiner Finger. Die Nummerierung ist in beiden Händen gleich.",
1:"Lege den rechten Daumen auf das <b>C (C4)</b> und jeden weiteren Finger auf die nächste weiße Taste. Jetzt liegen deine fünf Finger genau auf C-D-E-F-G. Das ist die „C-Lage“ — die erste Handlage, die jeder Pianist lernt.",
2:"C-Lage — Finger 1, 2, 3, 4, 5",
3:["Runde die Finger leicht, als hieltest du eine kleine Orange.","Halte das Handgelenk gerade — weder eingesunken noch angehoben.","Spiele 1-2-3-4-5 langsam, jeden Ton gleich laut.","Und wieder zurück: 5-4-3-2-1.","Wenn es fließt, schließe die Augen und spiele erneut."],
4:"<b>Gleichmäßige Lautstärke ist wichtiger als Tempo.</b> Der schwache Finger (4) wird immer leiser spielen wollen. Schenke ihm besondere Aufmerksamkeit.",
5:"Fingerübung Nr. 1",
6:{q:"Welcher Finger hat am Klavier die Nummer 1?",o:["Der kleine Finger","Der Mittelfinger","Der Daumen","Der Zeigefinger"],w:"Der Daumen ist immer Finger Nummer 1 — in beiden Händen."},
7:"Spiele die Übung fünfmal hintereinander fehlerfrei. Bei einem Fehler: langsamer neu beginnen."}},

"piano-3":{title:"Dein erstes Stück",goal:"Eine ganze Melodie nach Gehör und nach Noten spielen",b:{
0:"Jetzt ist es so weit: Du spielst ein Stück. „Morgen kommt der Weihnachtsmann“ geht auf eine französische Volksmelodie des 18. Jahrhunderts zurück (gemeinfrei) — Mozart schrieb sogar Variationen darüber.",
1:"Alle Töne liegen in der gelernten C-Lage, außer dem <b>A (A4)</b>, das wir mit leicht verschobenem kleinen Finger erreichen.",
2:"Twinkle, Twinkle — die vollständige Melodie",
3:"Die Töne, die du für das Stück brauchst",
4:["Höre die Melodie zweimal über die Wiedergabetaste an.","Spiele nur die ersten vier Töne: C C G G.","Ergänze: A A G (das G ist lang — zwei Schläge).","Weiter: F F E E D D C.","Füge alles langsam zusammen und erhöhe erst danach das Tempo."],
5:"<b>Die zentrale Regel des Selbstlernens:</b> langsam = schnell. Ein Gehirn, das langsam und fehlerfrei lernt, erreicht das Zieltempo dreimal schneller.",
6:{q:"In welchem Tempo beginnt man ein neues Stück richtig?",o:["So schnell wie möglich","In dem Tempo, in dem du fehlerfrei spielst","Im Originaltempo des Stücks","Das ist egal"],w:"Das richtige Tempo ist das, in dem es ohne Fehler gelingt. Das Tempo kommt danach von allein."},
7:"Spiele das Stück dreimal hintereinander ohne Unterbrechung."}},

"piano-4":{title:"Rhythmus — die Sprache der Zeit",goal:"1-2-3-4 zählen und verschiedene Notenwerte spielen",b:{
0:"Musik ist nicht nur, welche Töne — sondern <b>wann</b>. Die grundlegenden Notenwerte:",
1:["<b>Ganze Note</b> — dauert 4 Schläge.","<b>Halbe</b> — 2 Schläge.","<b>Viertel</b> — ein Schlag. Der häufigste Wert überhaupt.","<b>Achtel</b> — ein halber Schlag. Man zählt 1-und-2-und."],
2:"Rhythmusübung — im Vierertakt zählen",
3:"Die meisten populären Stücke haben <b>vier Schläge pro Takt</b> (4/4). Der erste Schlag ist stärker — er ist der Puls des Stücks.",
4:"Erst klatschen, dann spielen. Was du nicht klatschen kannst, kannst du auch nicht spielen.",
5:"Derselbe Ton, verschiedene Werte",
6:{q:"Wie viele Schläge dauert eine Viertelnote im 4/4-Takt?",o:["4","2","1","Einen halben"],w:"Eine Viertelnote = ein Schlag. Vier Viertel füllen einen ganzen Takt."},
7:"Stelle das Metronom auf 70 und klatsche genau auf die Schläge. Danach klatsche Achtel (zweimal pro Schlag)."}},

"piano-5":{title:"Die linke Hand kommt dazu",goal:"Eine einfache Bassbegleitung mit der linken Hand spielen",b:{
0:"Die linke Hand spielt die tiefen Töne — das harmonische Fundament. Wir beginnen einfach: ein Ton pro Takt.",
1:"C und G in der Oktave der linken Hand",
2:["Lege den kleinen Finger der linken Hand auf C (C3).","Lege den Daumen auf G (G3).","Spiele C — zähle 4. Spiele G — zähle 4.","Wenn es stabil ist, spiele C-G-C-G auf den Schlägen 1 und 3."],
3:"Die linke Hand fühlt sich am Anfang immer „dumm“ an. Das ist völlig normal — sie hatte im Leben schlicht weniger Training. Innerhalb einer Woche holt sie auf.",
4:"Bassübung",
5:{q:"Was ist die Hauptaufgabe der linken Hand im populären Klavierspiel?",o:["Die Melodie spielen","Bass und Harmonie spielen","Die Seiten umblättern","Nur den Takt halten"],w:"Die linke Hand baut das harmonische Fundament, auf dem die Melodie der rechten Hand ruht."},
6:"Spiele die Bassübung mit dem Metronom auf 70."}},

"piano-6":{title:"Beide Hände zusammen — der große Moment",goal:"Die Hände in einer einfachen Übung koordinieren",b:{
0:"Hier bleiben die meisten Selbstlernenden stecken, und zwar aus einem einzigen Grund: Sie führen die Hände zu früh zusammen.",
1:["Spiele die rechte Hand allein, bis sie völlig automatisch läuft.","Ebenso die linke Hand.","Spiele nur einen Takt mit beiden Händen — und halte an.","Füge jeweils einen Takt hinzu.","Wenn es hakt, geh zurück zu den Händen einzeln. Immer."],
2:"Übung für beide Hände (die Melodie)",
3:"Übung für beide Hände (der Bass)",
4:"<b>Ein Trick, der funktioniert:</b> Sage die Töne der rechten Hand laut, während du spielst. Das zwingt das Gehirn, die Hände zu trennen.",
5:{q:"Was tut man, wenn beide Hände nicht zusammengehen?",o:["Schneller spielen","Auf die linke Hand verzichten","Zurück zu einzelnen Händen und nur einen Takt zusammenfügen","Zu einem anderen Stück wechseln"],w:"In kleine Teile zerlegen und schrittweise zusammensetzen ist die einzige Methode, die funktioniert."},
6:"Spiele beide Übungen zusammen, nur zwei Takte, zehnmal."}},

"piano-7":{title:"C-Dur-Tonleiter und der Daumenuntersatz",goal:"Eine ganze Oktave mit einer Hand spielen",b:{
0:"Du hast nur fünf Finger — die Tonleiter hat acht Töne. Die Lösung ist der <b>Daumenuntersatz</b>, die wichtigste Bewegung der Klaviertechnik.",
1:"C-Dur-Tonleiter aufwärts",
2:["Rechte Hand: 1-2-3 auf C-D-E.","Während Finger 3 das E spielt, „wandert“ der Daumen unter die Handfläche.","Der Daumen landet auf F — und von dort 1-2-3-4-5 bis zum nächsten C.","Der vollständige Fingersatz: 1 2 3 1 2 3 4 5.","Abwärts: 5 4 3 2 1 3 2 1."],
3:"Ellbogen und Unterarm sollten sich leicht mit der Hand nach rechts bewegen. Bewegt sich nur der Daumen, wirkt es unbeholfen.",
4:"C-Dur-Tonleiter — hin und zurück",
5:{q:"Wann geht der Daumen in der aufwärts gespielten C-Dur-Tonleiter unter die Hand?",o:["Nach dem Ton D","Während Finger 3 das E spielt","Nach dem G","Er geht gar nicht unter"],w:"Der Untersatz geschieht, während Finger 3 das E spielt, damit der Daumen rechtzeitig auf dem F landet."},
6:"Spiele die Tonleiter hin und zurück viermal bei Metronom 60."}},

"piano-8":{title:"Akkorde — drei Töne, die alles verändern",goal:"C, F und G mit der linken Hand spielen",b:{
0:"Ein <b>Akkord</b> sind drei oder mehr Töne, die zusammen erklingen. Ein Dur-Akkord entsteht durch Überspringen: Ton, eine Taste überspringen, Ton, überspringen, Ton.",
1:"C-Dur-Akkord (C) — C-E-G",
2:"F-Dur-Akkord (F) — F-A-C",
3:"G-Dur-Akkord (G) — G-H-D",
4:"Diese drei Akkorde (C, F, G) reichen für Hunderte von Stücken. Sie sind die „großen Drei“ der Tonart.",
5:"Beachte, dass alle drei gleich gebaut sind: Finger 5-3-1 in der linken Hand, auf einer weißen Taste, überspringen, Taste, überspringen, Taste.",
6:{q:"Aus welchen Tönen besteht der C-Dur-Akkord?",o:["C-D-E","C-E-G","C-F-A","C-G-C"],w:"Ein Dur-Akkord wird aus der ersten, dritten und fünften Stufe der Tonleiter gebaut: C-E-G."},
7:"Wechsle zwischen C, F und G, vier Schläge pro Akkord, Metronom 60."}},

"piano-9":{title:"Begleitung — ein Stück mit Akkorden spielen",goal:"Melodie rechts mit Akkorden links verbinden",b:{
0:"Jetzt fügen wir zusammen: Die linke Hand spielt einen Akkord, die rechte die Melodie. So begleitet man jedes Lied der Welt.",
1:["Spiele „Twinkle“ mit der rechten Hand.","Im ersten Takt — Akkord C in der linken Hand.","Wenn die Melodie zu „A A G“ kommt — wechsle zu F und dann zu C.","Im vorletzten Takt — G, und zum Schluss wieder C."],
2:"Melodie zum Üben",
3:"<b>Woran erkennt man den passenden Akkord?</b> Prüfe, welcher Akkord den Ton enthält, den die Melodie auf diesem Schlag spielt. Spielt die Melodie E, passt C (C-E-G).",
4:{q:"Welcher Akkord enthält den Ton A?",o:["C (C-E-G)","G (G-H-D)","F (F-A-C)","Keiner"],w:"Der F-Akkord besteht aus F-A-C und enthält daher den Ton A."},
5:"Spiele das Stück mit Begleitung, sehr langsam, zweimal."}},

"piano-10":{title:"Dur und Moll — die emotionale Farbe",goal:"Moll-Akkorde erkennen und spielen",b:{
0:"Der Unterschied zwischen „fröhlich“ und „traurig“ ist in der Musik <b>ein Halbton</b>. Schiebe den mittleren Ton eines Dur-Akkords eine Taste nach links — und du hast Moll.",
1:"a-Moll-Akkord (Am) — A-C-E",
2:"d-Moll-Akkord (Dm) — D-F-A",
3:"e-Moll-Akkord (Em) — E-G-H",
4:"Spiele C und danach Am direkt hintereinander. Achte darauf, wie sich die Stimmung des Klangs sofort ändert. Das ist die Kraft der Harmonie.",
5:{q:"Was unterscheidet einen Dur- von einem Moll-Akkord?",o:["Moll ist höher","Der mittlere Ton liegt in Moll einen Halbton tiefer","Moll hat vier Töne","Es gibt keinen echten Unterschied"],w:"Der mittlere Ton (die Terz) sinkt um einen Halbton — und darin besteht der ganze Unterschied zwischen „fröhlich“ und „traurig“."},
6:"Spiele die Folge C – Am – F – G, vier Schläge pro Akkord. Das ist die häufigste Folge der populären Musik."}},

"piano-11":{title:"Dynamik, Pedal und Ausdruck",goal:"Technisches Spiel in musikalisches verwandeln",b:{
0:"Zwei Menschen spielen dieselben Töne — und einer klingt wie ein Roboter. Der Unterschied ist die <b>Dynamik</b>: die Veränderung der Lautstärke.",
1:["<b>Piano (p)</b> — leise. <b>Forte (f)</b> — laut.","<b>Crescendo</b> — allmählich lauter. <b>Diminuendo</b> — allmählich leiser.","Spiele die Tonleiter: leise beginnen, Höhepunkt beim oberen C, beim Abstieg leiser werden.","Eine musikalische Phrase ist wie ein gesprochener Satz — sie hat Anfang, Höhepunkt und Ende."],
2:"<b>Das rechte Pedal</b> hebt die Dämpfer von den Saiten — und der Klang klingt weiter. Die Regel: bei jedem Akkordwechsel das Pedal wechseln, sonst entsteht Matsch.",
3:"Die richtige Technik: Das Pedal wird <b>direkt nachdem</b> der Finger gespielt hat getreten, nicht davor. Das nennt man „verzögertes Pedal“.",
4:{q:"Wann wechselt man das Pedal?",o:["Bei jedem Ton","Bei jedem Akkordwechsel","Nur am Ende des Stücks","Nie, man hält es gedrückt"],w:"Ein Pedalwechsel bei jedem Akkordwechsel hält den Klang sauber."},
5:"Spiele die Tonleiter mit Crescendo aufwärts und Diminuendo abwärts."}},

"piano-12":{title:"Abschlussstück — Ode an die Freude",goal:"Ein vollständiges klassisches Werk spielen",b:{
0:"Du hast den Grundkurs beendet. Zeit für ein echtes Werk: das Thema aus Beethovens Neunter Sinfonie (1824) — gemeinfrei.",
1:"Ode an die Freude",
2:["Spiele die rechte Hand allein, jeweils vier Takte.","Ergänze einen einfachen Bass links: C – C – G – C.","Füge Dynamik hinzu: leiser Beginn, Höhepunkt in der Mitte.","Ergänze Pedal bei den Akkordwechseln.","Spiele von Anfang bis Ende ohne anzuhalten — auch wenn ein Fehler passiert."],
3:"<b>Die Regel erfahrener Spieler:</b> Im Vortrag hält man nicht an, um zu korrigieren. Man spielt weiter. Korrekturen gehören ins Üben, nicht ins Spielen.",
4:{q:"Was ist die wirksamste Art, ein neues Stück zu üben?",o:["Es immer wieder von vorne bis hinten spielen","Die schweren Stellen isolieren und nur diese üben","Nur die leichten Teile spielen","Nur Aufnahmen hören"],w:"Gezieltes Üben der schwierigen Stellen spart Stunden. 80 % der Zeit gehören den schwersten 20 %."},
5:"Nimm dich beim Spielen mit dem Handy auf und höre es dir an. Du wirst Dinge hören, die dir beim Spielen entgangen sind."}},

/* ===================== GITARRE ===================== */
"guitar-1":{title:"Die Gitarre kennenlernen und richtig halten",goal:"Richtig sitzen, richtig halten und die Gitarre stimmen",b:{
0:"Die Gitarre hat sechs Saiten. Die dickste (oben) ist das <b>tiefe E</b>, die dünnste (unten) das <b>hohe E</b>. Die Saiten werden <b>von dünn nach dick</b> nummeriert: Die dünnste ist Saite 1.",
1:["Saite 6 — tiefes E (E2)","Saite 5 — A (A2)","Saite 4 — D (D3)","Saite 3 — G (G3)","Saite 2 — H (B3)","Saite 1 — hohes E (E4)"],
2:"Der Klang der leeren Saiten — von dick nach dünn",
3:"<b>Richtig sitzen:</b> Rücken gerade, Gitarrenkorpus auf dem rechten Bein (für Rechtshänder), Hals leicht nach oben geneigt. Daumen der linken Hand hinter dem Hals — er lugt nicht oben hervor.",
4:"Schmerzende Fingerkuppen in den ersten zwei Wochen sind normal — die Haut wird fester. Schmerzen im Handgelenk oder in der Schulter sind <b>nicht</b> normal und deuten auf eine falsche Haltung hin. Halte an und korrigiere die Sitzposition.",
5:"Stimme die Gitarre vor jedem Üben. Eine verstimmte Gitarre bringt deinem Gehör falsche Tonhöhen bei. Nutze das <a href='#/tools/tuner'>Stimmgerät der App</a>.",
6:{q:"Welche Saite ist Saite Nummer 1?",o:["Die dickste","Die dünnste","Die mittlere","Das hängt von der Gitarre ab"],w:"Saite 1 ist die dünnste — das hohe E."},
7:"Stimme die Gitarre, zupfe dann jede leere Saite und sage ihren Namen laut."}},

"guitar-2":{title:"Die rechte Hand — dein erstes Anschlagen",goal:"Einen sauberen, gleichmäßigen Klang auf leeren Saiten erzeugen",b:{
0:"Die rechte Hand ist für Klang und Rhythmus zuständig. Man kann mit Plektrum oder mit den Fingern spielen — wir beginnen mit dem Plektrum.",
1:["Halte das Plektrum zwischen Daumen und Zeigefinger, sodass nur 3–5 mm herausschauen.","Die Bewegung kommt aus dem Handgelenk, nicht aus dem Ellbogen.","Schlage abwärts über alle sechs Saiten — ein durchgehender Klang.","Nun aufwärts, von der dünnen zur dicken Saite.","Übe: runter, runter, runter, runter — in gleichmäßigem Tempo."],
2:"Viertelschläge — vier Zählzeiten",
3:"Wenn der Klang „stolpert“, hältst du das Plektrum wahrscheinlich zu fest. Ein lockerer Griff erzeugt einen glatten Klang.",
4:{q:"Woher soll die Schlagbewegung kommen?",o:["Aus der Schulter","Aus dem Ellbogen","Aus dem Handgelenk","Nur aus den Fingern"],w:"Eine Bewegung aus dem Handgelenk ist locker, schnell und führt nicht zu Verletzungen."},
5:"Schlage 2 Minuten am Stück leere Saiten an, Metronom 70. Achte auf Gleichmäßigkeit."}},

"guitar-3":{title:"Der erste Akkord — Em",goal:"Einen sauberen Akkord greifen und ihn im Takt anschlagen",b:{
0:"Em (e-Moll) ist der einfachste Akkord der Welt: nur zwei Finger, und alle sechs Saiten werden gespielt.",
1:null,
2:["Finger 2 auf Bund 2 der Saite 5 (A).","Finger 3 auf Bund 2 der Saite 4 (D).","Drücke nahe am Bundstäbchen — nicht darauf und nicht in der Mitte.","Die Finger stehen auf der Kuppe, sie liegen nicht flach.","Zupfe Saite für Saite und prüfe, ob jede sauber klingt."],
3:"Ein „toter“ oder schnarrender Klang? Fast immer liegt ein Finger flach auf und berührt eine Nachbarsaite. Hebe die Handfläche an und runde die Finger stärker.",
4:"Die Prüfmethode der Lehrenden: Zupfe jede Saite einzeln (ein „Arpeggio“). Die Saite, die nicht klingt, zeigt dir genau, welchen Finger du korrigieren musst.",
5:{q:"Was tun, wenn eine Saite im Akkord schnarrt?",o:["Mit allen Fingern fester drücken","Prüfen, welcher Finger flach aufliegt und eine Nachbarsaite berührt","Die Gitarre neu stimmen","Die Saiten wechseln"],w:"In 90 % der Fälle berührt ein Nachbarfinger die Saite. Die Lösung ist Rundung der Finger, nicht Kraft."},
6:"Halte Em und schlage 16 Zählzeiten durch. Loslassen, Hand ausschütteln, wiederholen — fünfmal."}},

"guitar-4":{title:"Ein zweiter Akkord und der erste Wechsel",goal:"Zwischen Em und Am wechseln, ohne anzuhalten",b:{
0:"Am (a-Moll) ist genau dieselbe Form wie Em — nur um eine Saite verschoben, mit einem zusätzlichen Finger.",
1:null,
2:["Nimm die Em-Form und verschiebe sie um eine Saite Richtung dünne Saiten.","Ergänze Finger 1 auf Bund 1 der Saite 2 (H).","Schlage Saite 6 nicht an.","Wechsle Em → Am → Em → Am, ohne anzuschlagen — nur die Hand."],
3:"<b>Das Geheimnis der Wechsel:</b> Übe den Wechsel <u>ohne Anschlag</u>, 20-mal. Das Gehirn lernt die Bewegung ohne den Druck des Klangs. Danach kommt der Anschlag dazu.",
4:"<b>Ankerfinger:</b> Zwischen Em und Am behalten zwei Finger dieselbe Form. Hebe nicht die ganze Hand — schiebe sie.",
5:{q:"Wie übt man einen Akkordwechsel am wirksamsten?",o:["Das Stück schnell immer wieder spielen","Nur die Handbewegung üben, ohne Anschlag","Jeden Akkord einzeln üben","Nur mit schnellem Metronom üben"],w:"Die Trennung von Handbewegung und Anschlag lässt das Gehirn die Bewegung sauber und schnell lernen."},
6:"60 Wechsel Em↔Am. Zähle laut mit. Eine Übung von vier Minuten, die alles verändert."}},

"guitar-5":{title:"Das Schlagmuster — runter und rauf",goal:"Das weltweit häufigste Begleitmuster spielen",b:{
0:"Das grundlegendste Muster: <b>runter, runter-rauf, rauf-runter-rauf</b>. Wenn du in deinem Leben nur ein Schlagmuster lernst, dann dieses.",
1:["Zähle laut: 1 und 2 und 3 und 4 und.","Die Hand bewegt sich ständig auf und ab — wie ein Pendel, ohne Pause.","Auf den Zählzeiten, die nicht gespielt werden, bewegt sich die Hand weiter in der Luft, sie berührt nur nicht.","Das Muster: ↓ . ↓↑ . ↑↓↑ (1, 2-und, 3-und-4-und)."],
2:"Das grundlegende Begleitmuster",
3:"Die Hand, die nie stehen bleibt, ist das Geheimnis. Anfänger stoppen die Hand — und verlieren den Takt. Lass sie immer in Bewegung.",
4:{q:"Warum soll sich die rechte Hand auch dann bewegen, wenn nicht angeschlagen wird?",o:["Damit es gut aussieht","Um das durchgehende Rhythmusgefühl zu bewahren","Damit die Hand nicht ermüdet","Das ist unwichtig"],w:"Die durchgehende Bewegung ist deine innere Uhr. Ein Stopp zerbricht den Rhythmus."},
5:"Spiele Em mit diesem Muster eine volle Minute ohne Unterbrechung, danach Am."}},

"guitar-6":{title:"Der C-Akkord — und ein anspruchsvollerer Wechsel",goal:"Ein sauberes C greifen und in eine Folge einbauen",b:{
0:"C (C-Dur) verlangt drei Finger in drei verschiedenen Bünden. Das ist der Akkord, der die Durchhaltenden von den Aufgebenden trennt.",
1:null,
2:["Finger 1 — Bund 1, Saite 2.","Finger 2 — Bund 2, Saite 4.","Finger 3 — Bund 3, Saite 5.","Schlage Saite 6 nicht an.","Achte darauf, dass die leeren Saiten 1 und 3 frei klingen."],
3:"Wenn Saite 1 (die dünne) nicht klingt, liegt dein Finger 1 darauf. Drehe das Handgelenk leicht nach vorn.",
4:{q:"Welche Saiten werden im offenen C-Akkord nicht gespielt?",o:["Saite 1","Saite 6","Saiten 5 und 6","Es werden alle gespielt"],w:"Beim C-Akkord beginnt man auf der fünften Saite. Die sechste gehört nicht zum Akkord."},
5:"Übe C → Am → C → Am, jeweils vier Zählzeiten."}},

"guitar-7":{title:"G und D — dein erstes Drei-Akkorde-Stück",goal:"Ein ganzes Stück mit G, C und D spielen",b:{
0:"Mit G, C und D lassen sich Tausende von Stücken spielen. Das ist die „G-Familie“ — die drei zentralen Akkorde der Tonart G-Dur.",
1:null,2:null,
3:"<b>Die klassische Struktur:</b> G – G – C – C – G – G – D – C – G. Vier Zählzeiten pro Akkord.",
4:"Begleitmuster für das Stück",
5:"Beachte: Beim Wechsel von G nach C kann Finger 3 im selben Bund bleiben — ein „Ankerfinger“, der den Wechsel halbiert.",
6:{q:"Was haben die Akkorde G, C und D gemeinsam?",o:["Sie sind alle Moll","Sie sind die drei zentralen Akkorde der G-Dur-Tonleiter","Sie liegen im selben Bund","Sie nutzen dieselben Finger"],w:"Es sind die Stufen I, IV und V der G-Dur-Tonleiter — das harmonische Skelett der meisten Songs."},
7:"Spiele den Zyklus G-C-G-D zweimal ohne anzuhalten, auch wenn die Wechsel langsam sind."}},

"guitar-8":{title:"Schnelle Wechsel und Ankerfinger",goal:"Die Wechselzeit zwischen Akkorden verkürzen",b:{
0:"Langsame Wechsel sind das Problem Nummer eins bei Gitarrenanfängern. Die Lösung ist weder Kraft noch Tempo — sondern <b>Effizienz</b>.",
1:["<b>Ankerfinger:</b> Finde einen Finger, der zwischen zwei Akkorden liegen bleibt — hebe ihn nicht.","<b>Minimale Bewegung:</b> Hebe die Finger nur 2 mm von den Saiten.","<b>Timing:</b> Wechsle auf der letzten Zählzeit, nicht danach.","<b>Die Uhr-Übung:</b> Stelle eine Minute und zähle deine sauberen Wechsel. Übertriff deinen Rekord täglich."],
2:"Trage deinen Wechselrekord ins Übe-Tagebuch der App ein. Messbarer Fortschritt ist der stärkste Motor für Beständigkeit.",
3:{q:"Was ist ein „Ankerfinger“?",o:["Der Daumen hinter dem Hals","Ein Finger, der beim Wechsel zwischen zwei Akkorden liegen bleibt","Der stärkste Finger","Ein Finger, der zwei Saiten drückt"],w:"Ein Ankerfinger verkürzt den Wechsel und dient den anderen Fingern als Bezugspunkt."},
4:"Eine Minute Wechsel C↔G. Notiere die Zahl. Komm morgen wieder und übertriff sie."}},

"guitar-9":{title:"Schlagmuster — die Begleitung variieren",goal:"Drei verschiedene Schlagmuster kennen",b:{
0:"Dieselben Akkorde mit einem anderen Schlagmuster klingen wie ein völlig anderes Stück. Hier sind drei Muster, die fast jeden Stil abdecken.",
1:"Muster 1 — langsame Ballade",
2:"Muster 2 — Standard-Pop",
3:"Muster 3 — Offbeat-Betonung",
4:"<b>Das Offbeat-Muster</b> — Anschlag nur auf dem „und“ zwischen den Zählzeiten — erzeugt ein federndes Gefühl und passt zu Reggae, Ska und vielen Folkstilen.",
5:{q:"Was ändert sich, wenn man dieselben Akkorde mit einem anderen Muster spielt?",o:["Die Harmonie","Charakter und Stil des Stücks","Die Tonhöhe","Nur das Tempo"],w:"Das Schlagmuster bestimmt den Stil. Dieselben vier Akkorde können nach Ballade, Rock oder Reggae klingen."},
6:"Spiele dieselbe Akkordfolge mit allen drei Mustern."}},

"guitar-10":{title:"Dein erstes Solo — die Pentatonik",goal:"Ein kurzes Solo über fünf Tönen improvisieren",b:{
0:"Die Pentatonik (fünf Töne) ist das Geheimnis jedes Rock- und Blues-Solisten. Ihr Zauber: Man kann darin kaum einen „falschen“ Ton spielen.",
1:"a-Moll-Pentatonik — aufwärts",
2:["Setze Finger 1 auf Bund 5, Saite 6 (A).","Das Muster: 5-8 auf den Saiten 6 und 5, 5-7 auf den Saiten 4 und 3, 5-8 auf den Saiten 2 und 1.","Spiele das Muster auf und ab, bis die Finger es sich merken.","Vergiss nun die Reihenfolge — spiele die Töne in beliebiger Folge. Das ist Improvisation."],
3:"Ein gutes Solo besteht nicht aus vielen Tönen — sondern aus Tönen mit <b>Pausen</b> dazwischen. Lass Raum zum Atmen.",
4:{q:"Warum lässt sich mit der Pentatonik leicht improvisieren?",o:["Sie enthält nur hohe Töne","Sie enthält 5 Töne, die alle harmonisch passen","Man kann sie nur auf einer Saite spielen","Sie wird langsam gespielt"],w:"Die „reibenden“ Töne wurden aus der Tonleiter entfernt — deshalb klingt jede Kombination gut."},
5:"Improvisiere 8 Takte in der Pentatonik über einem Metronom."}},

"guitar-11":{title:"Akkordfamilien — A, E, Dm",goal:"Den Akkordvorrat auf acht erweitern",b:{
0:null,1:null,2:null,
3:"Mit den acht gelernten Akkorden (Em, Am, C, G, D, A, E, Dm) kannst du die große Mehrheit populärer Songs spielen.",
4:"<b>Die Passungsregel:</b> Akkorde derselben „Familie“ (Tonart) klingen gut zusammen. C-Familie: C, Dm, Em, F, G, Am. G-Familie: G, Am, Bm, C, D, Em.",
5:{q:"Welcher Akkord gehört nicht zur G-Dur-Familie?",o:["C","D","Em","F"],w:"F gehört nicht zur G-Dur-Tonleiter (die ein Fis enthält). Es gehört zur C-Familie."},
6:"Wähle vier Akkorde einer Familie und spiele sie im Kreis."}},

"guitar-12":{title:"Abschlussstück und Ausblick — der Barré",goal:"Ein ganzes Stück spielen und die nächste Stufe kennenlernen",b:{
0:"Du hast den Grundkurs beendet. Du kannst stimmen, anschlagen, acht Akkorde greifen, drei Muster und ein Solo spielen.",
1:"Abschlussmelodie — Amazing Grace (gemeinfrei)",
2:"<b>Die nächste Stufe: der Barré-Akkord.</b> Finger 1 legt sich flach über alle Saiten und ahmt einen Kapodaster nach. Das öffnet den gesamten Hals.",
3:["Lege Finger 1 flach über alle sechs Saiten im 1. Bund.","Nutze die Außenseite des Fingers, nicht die weiche Kuppe.","Ergänze die E-Form mit den Fingern 2, 3 und 4 — und du hast ein F.","Nicht verzweifeln: Ein sauberer Barré dauert bei den meisten 2 bis 4 Wochen."],
4:"Wenn du beim Barré Schmerzen im Handgelenk spürst — halte an. Das Problem ist der Daumenwinkel, nicht fehlende Kraft. Übe im 5. Bund, wo die Saiten weicher sind.",
5:{q:"Was ist ein Barré-Akkord?",o:["Ein Akkord, der nur leere Saiten nutzt","Ein Akkord, bei dem ein Finger mehrere Saiten gleichzeitig drückt","Ein Akkord mit vier Tönen","Ein schneller Akkord"],w:"Finger 1 erzeugt einen „beweglichen Sattel“ und erlaubt es, Akkordformen über den ganzen Hals zu verschieben."},
6:"Spiele ein ganzes Stück aus der Bibliothek mit Begleitung und nimm dich auf."}},

/* ===================== UKULELE ===================== */
"ukulele-1":{title:"Ukulele in 10 Minuten",goal:"Den ersten Akkord greifen und anschlagen",b:{
0:"Die Ukulele ist das schnellste Einstiegsinstrument der Welt: vier weiche Nylonsaiten und die Standardstimmung <b>G-C-E-A</b>.",
1:"Die leeren Saiten",2:null,
3:["Halte die Ukulele mit dem rechten Unterarm an den Körper.","Setze Finger 3 auf Bund 3 der dünnen Saite (A).","Schlage sanft abwärts mit der Kuppe des Zeigefingers.","Fertig — du hast einen C-Akkord gespielt."],
4:"Auf der Ukulele schlägt man dort an, wo der Hals auf den Korpus trifft — dort ist der Klang am vollsten.",
5:{q:"Wie lautet die Standardstimmung einer Sopran-Ukulele?",o:["E-A-D-G","G-C-E-A","C-F-A-D","D-G-B-E"],w:"G-C-E-A ist die Standardstimmung, und das G liegt tatsächlich höher als das C („High-G-Stimmung“)."},
6:"Schlage den C-Akkord eine Minute lang gleichmäßig an."}},

"ukulele-2":{title:"Zwei Akkorde = ein ganzes Lied",goal:"Zwischen C und Am wechseln",b:{
0:null,
1:"Auch Am braucht nur einen Finger — Finger 2 auf Bund 2 der dicken Saite (G).",
2:"Einfaches Muster — vier Abschläge",
3:"Spiele vier Zählzeiten C, vier Zählzeiten Am und wiederhole. Das ist bereits eine gültige Liedform, über die man singen kann.",
4:{q:"Wie viele Finger braucht der Am-Akkord auf der Ukulele?",o:["Einen","Zwei","Drei","Vier"],w:"Nur einen Finger, auf Bund 2 der dicken Saite."},
5:"30 Wechsel C↔Am mit langsamem Metronom."}},

"ukulele-3":{title:"Der dritte Akkord — F",goal:"Eine Folge aus drei Akkorden spielen",b:{
0:null,
1:"Mit C, Am und F lassen sich bereits Hunderte Lieder spielen. Die Folge C – Am – F – C ist ein Klassiker.",
2:"Pop-Muster",
3:{q:"Welche gängige Folge nutzt diese drei Akkorde?",o:["F – F – F – F","C – Am – F – C","C – C# – D","Nur Am"],w:"C – Am – F ist eine der häufigsten Folgen der populären Musik."},
4:"Spiele die Folge C-Am-F-C viermal hintereinander."}},

"ukulele-4":{title:"Muster und wie man variiert",goal:"Drei Begleitmuster",b:{
0:"Insel-Muster",1:"Walzer — drei Zählzeiten",
2:"Das „Insel-Muster“ (runter, runter-rauf, rauf-runter-rauf) ist der klassische Ukulele-Sound.",
3:"Halte die rechte Hand völlig locker. Auf der Ukulele bedeutet Kraft einen rauen Klang.",
4:{q:"Wie viele Zählzeiten hat ein Walzertakt?",o:["2","3","4","6"],w:"Der Walzer steht im 3/4-Takt — drei Zählzeiten pro Takt, mit Betonung auf der ersten."},
5:"Spiele die gelernte Folge mit zwei verschiedenen Mustern."}},

"ukulele-5":{title:"G und Em — das Repertoire öffnen",goal:"Fünf Akkorde beherrschen",b:{
0:null,1:null,
2:"G verlangt drei Finger im Dreieck, Em ist eine absteigende Diagonale. Beide brauchen anfangs langsames Üben.",
3:"Übe den Wechsel C→G ohne Anschlag, 20-mal. Du wirst merken, wie die Hand die Form innerhalb von Minuten „lernt“.",
4:{q:"Was hilft am meisten, einen neuen Akkordwechsel zu beherrschen?",o:["Schnell spielen","Die Bewegung ohne Anschlag üben","Fester drücken","Die Saiten wechseln"],w:"Die Trennung von Bewegung und Klang beschleunigt das motorische Lernen."},
5:"30 Wechsel C↔G und 30 Wechsel Am↔Em."}},

"ukulele-6":{title:"Fingerpicking",goal:"Ein einfaches Arpeggio spielen",b:{
0:"Statt alle Saiten zusammen anzuschlagen, zupfen wir sie nacheinander — das nennt man <b>Arpeggio</b> und passt zu ruhigen Liedern.",
1:["Daumen — Saite 4 (G).","Zeigefinger — Saite 3 (C).","Mittelfinger — Saite 2 (E).","Ringfinger — Saite 1 (A).","Spiele 4-3-2-1 und dann 1-2-3-4."],
2:"Arpeggio auf dem C-Akkord",
3:{q:"Was ist ein Arpeggio?",o:["Ein kräftiger Anschlag","Die Töne eines Akkords nacheinander spielen","Ein schneller Akkordwechsel","Eine Plektrumart"],w:"Arpeggio = „gebrochener Akkord“ — die Töne erklingen nacheinander statt gleichzeitig."},
4:"Spiele ein Arpeggio auf C, Am und F, je vier Zählzeiten."}},

"ukulele-7":{title:"Melodie auf der Ukulele",goal:"Melodie spielen, nicht nur begleiten",b:{
0:"Die Ukulele kann auch Melodien spielen. Wir nutzen die Saiten C, E und A.",
1:"Twinkle, Twinkle — Melodie",
2:"Markiere die Töne anfangs mit kleinen Aufklebern auf dem Hals — eine völlig legitime Abkürzung.",
3:{q:"Was bringt es, Melodien auf dem Instrument zu spielen?",o:["Es ist leichter als Akkorde","Es schult Gehör und das Wissen, wo jeder Ton liegt","Es klingt lauter","Es bringt nichts"],w:"Melodiespiel verbindet Gehör und Griffbrett — eine Fähigkeit, die durch nichts zu ersetzen ist."},
4:"Spiele die Melodie zweimal langsam."}},

"ukulele-8":{title:"Singen und spielen gleichzeitig",goal:"Begleitung mit Gesang verbinden",b:{
0:"Das ist die Fähigkeit, die dich zu der Person macht, die man ans Lagerfeuer einlädt. Das Geheimnis ist <b>Automatisierung</b>: Die Hand muss spielen, ohne dass du an sie denkst.",
1:["Spiele die Begleitung, bis du dabei ein Gespräch führen könntest.","Sprich den Text im Rhythmus, ohne zu singen.","Summe die Melodie beim Spielen.","Erst jetzt — singe Text und Melodie zusammen."],
2:"Wenn der Gesang die Hand „mitzieht“, hör auf zu singen, stabilisiere die Hand und versuch es erneut. Die Hand ist der Anker.",
3:{q:"Was ist die Voraussetzung dafür, gleichzeitig zu singen und zu spielen?",o:["Eine gute Stimme","Dass die Begleitung völlig automatisch läuft","Komplizierte Akkorde","Ein Metronom"],w:"Automatische Begleitung macht die Aufmerksamkeit für den Gesang frei."},
4:"Spiele Begleitung und summe eine Minute lang eine Melodie."}},

"ukulele-9":{title:"Abschlussstück und Ausblick",goal:"Ein ganzes Lied von Anfang bis Ende spielen",b:{
0:"Hava Nagila — traditionelle Melodie (gemeinfrei)",
1:"Die nächsten Schritte auf der Ukulele: Barré-Akkorde, die „Chunk“-Technik (rhythmisches Abdämpfen) und fortgeschrittenes Fingerpicking.",
2:"Such dir jemanden zum Zusammenspielen. Gemeinsames Spiel verbessert das Rhythmusgefühl weit mehr als jedes Üben allein.",
3:{q:"Welcher Schritt wird nach den offenen Akkorden empfohlen?",o:["Das Instrument wechseln","Barré-Akkorde und fortgeschrittene Muster","Aufhören zu üben","Nur Noten lernen"],w:"Der Barré öffnet den ganzen Hals und erlaubt das Spiel in jeder Tonart."},
4:"Nimm dich beim Spielen eines ganzen Liedes auf."}},

/* ===================== BLOCKFLÖTE ===================== */
"recorder-1":{title:"Atem und erster Griff",goal:"Einen sauberen Ton erzeugen und H spielen",b:{
0:"Die Blockflöte ist das perfekte Einstiegsinstrument: günstig, leicht, und sie verlangt weder Kraft noch große Hände.",
1:["Halte die Flöte in etwa 45 Grad zum Körper.","Linke Hand oben — immer! Das ist der häufigste Fehler.","Lege die Spitze des Mundstücks auf die Unterlippe und schließe die Lippen sanft — ohne zu beißen.","Blase sanft und flüstere „tü“ — das ist der Zungenstoß, mit dem jeder Ton beginnt."],
2:"Zu kräftiges Blasen ergibt einen schrillen, spitzen Klang. Die Flöte braucht <b>sehr wenig</b> Luft. Weniger ist mehr.",
3:"Der Ton H (B)",
4:"Erster Ton: Der linke Daumen schließt das hintere Loch, der linke Zeigefinger das oberste. Das ist schon das H.",
5:{q:"Welche Hand ist auf der Blockflöte immer oben?",o:["Die rechte","Die linke","Das hängt davon ab, ob man Linkshänder ist","Das ist egal"],w:"Die linke Hand ist immer oben — bei allen Holzblasinstrumenten."},
6:"Spiele 10 lange, stabile H, jeweils 4 Sekunden."}},

"recorder-2":{title:"Drei Töne — H, A, G",goal:"Eine kurze Melodie spielen",b:{
0:["<b>H (B)</b> — Daumen + Finger 1 der linken Hand.","<b>A</b> — Finger 2 links kommt dazu.","<b>G</b> — Finger 3 links kommt dazu."],
1:"Übung mit drei Tönen",
2:"Achte darauf, dass die Finger die Löcher <b>vollständig</b> schließen — mit der Kuppe, nicht mit der Spitze. Ein halb offenes Loch erzeugt ein Quietschen.",
3:{q:"Was passiert, wenn ein Loch nicht vollständig geschlossen ist?",o:["Der Ton ist zu tief","Der Ton quietscht oder pfeift","Es passiert nichts","Die Flöte geht kaputt"],w:"Luft, die durch ein halb offenes Loch entweicht, erzeugt ein Pfeifen."},
4:"Spiele die Übung 5-mal ohne jeden Quietscher."}},

"recorder-3":{title:"Das erste Stück",goal:"Eine bekannte Melodie spielen",b:{
0:"Mary Had a Little Lamb — Volksmelodie (gemeinfrei)",
1:"Dieses Stück nutzt die bereits gelernten Töne plus C und D — die Finger der rechten Hand kommen dazu.",
2:"Summe die Melodie zuerst und spiele sie erst danach. Ein Gehör, das die Melodie kennt, führt die Finger.",
3:{q:"Welcher Schritt wird vor dem Spielen eines neuen Stücks empfohlen?",o:["Es schnell spielen","Es summen und die Melodie kennenlernen","Die Noten laut lesen","Das Instrument stimmen"],w:"Ein Gehör, das die Melodie kennt, erkennt einen Fehler sofort."},
4:"Spiele das ganze Stück zweimal."}},

"recorder-4":{title:"Zungenstoß und Artikulation",goal:"Töne sauber trennen",b:{
0:"Ohne Zungenstoß verschmelzen alle Töne zu einem einzigen langen Klang. Die Zunge ist die Zeichensetzung deines Spiels.",
1:["<b>„Tü“</b> — ein klarer Beginn für jeden Ton.","<b>„Dü“</b> — ein weicher Beginn, für gesangliche Stellen.","<b>Legato</b> — Zungenstoß nur beim ersten Ton der Gruppe.","<b>Staccato</b> — kurze, getrennte Töne."],
2:"Staccato gegen Legato",
3:{q:"Wozu dient die Zunge beim Blockflötenspiel?",o:["Um den Ton hoch zu halten","Um Töne sauber zu trennen und zu beginnen","Um lauter zu spielen","Um das Instrument zu stimmen"],w:"Die Zunge bestimmt den Beginn jedes Tons — ohne sie klingt das Spiel verwaschen."},
4:"Spiele eine ganze Tonleiter einmal staccato und einmal legato."}},

"recorder-5":{title:"Die vollständige C-Dur-Tonleiter",goal:"Eine ganze Oktave spielen",b:{
0:"C-Dur-Tonleiter",
1:"Eine vollständige Tonleiter verlangt das Zusammenspiel beider Hände. Die Hauptschwierigkeit: der Übergang von den Tönen der linken zu denen der rechten Hand.",
2:"Übe nur den Problemübergang (G→F) zwanzigmal, statt die ganze Tonleiter immer wieder zu spielen.",
3:{q:"Was ist bei einer schwierigen Stelle besser?",o:["Die ganze Stelle immer wieder spielen","Die zwei problematischen Töne isolieren und nur diese üben","Die Stelle überspringen","Das ganze Stück verlangsamen"],w:"Gezieltes Üben ist um ein Vielfaches wirksamer als das Wiederholen des Ganzen."},
4:"Spiele die Tonleiter hin und zurück 5-mal bei Metronom 60."}},

"recorder-6":{title:"Die zweite Oktave",goal:"Hohe Töne mit dem Daumen erzeugen",b:{
0:"Um eine Oktave höher zu kommen, „kneift“ der Daumen das hintere Loch — er öffnet es nur minimal. Das ist die Technik des <b>Überblasens</b>.",
1:["Schiebe den Daumen so, dass der Nagel einen kleinen Spalt öffnet.","Erhöhe den Luftdruck leicht.","Spiele tiefes G und hohes G im Wechsel."],
2:"Oktaven",
3:"Schriller Klang? Der Spalt ist zu groß. Tiefer Klang? Der Spalt ist geschlossen. Der Unterschied beträgt einen Millimeter.",
4:{q:"Welche Rolle hat der linke Daumen bei hohen Tönen?",o:["Vollständig schließen","Einen kleinen Spalt öffnen","Nur das Instrument halten","Vollständig öffnen"],w:"Ein kleiner Spalt verändert den Schwingungsmodus und hebt den Ton um eine Oktave."},
5:"Spiele die Oktavübung 10-mal."}},

"recorder-7":{title:"Kreuze und Bes",goal:"Halbtöne spielen",b:{
0:"Auf der Blockflöte erzeugt man Halbtöne mit <b>Gabelgriffen</b> — man schließt nicht aufeinanderfolgende Löcher.",
1:"Fis (F#) ist der wichtigste Ton zum Lernen — er wird in jedem Stück in G-Dur gebraucht.",
2:"G-Dur-Tonleiter (mit Fis)",
3:{q:"Was ist ein Gabelgriff?",o:["Alle Löcher schließen","Nicht aufeinanderfolgende Löcher schließen, um einen Halbton zu erzeugen","Alle Löcher öffnen","Ein Griff mit beiden Händen"],w:"Ein übersprungenes Loch in der Mitte des Griffs senkt den Ton um einen Halbton."},
4:"Spiele die G-Dur-Tonleiter hin und zurück."}},

"recorder-8":{title:"Ausdruck, Atmung und Phrasierung",goal:"Musikalisch statt mechanisch spielen",b:{
0:"Atmen ist nicht nur ein körperliches Bedürfnis — es ist Zeichensetzung. Man atmet am Ende einer musikalischen Phrase, nicht mitten im Wort.",
1:["Markiere in den Noten, wo du atmest — bevor du zu spielen beginnst.","Atme durch den Mund ein, schnell und leise.","Atme nicht mitten in einem langen Ton.","Beende eine Phrase mit einem sanften Zurücknehmen."],
2:"Spiele eine musikalische Phrase, als sprächst du einen Satz: Anfang, Höhepunkt und abgemildertes Ende.",
3:{q:"Wo atmet man richtig?",o:["Alle zwei Zählzeiten","Am Ende einer musikalischen Phrase","Immer wenn die Luft ausgeht","Mitten in einem langen Ton"],w:"Ein geplanter Atemzug am Phrasenende erhält die musikalische Linie."},
4:"Spiele ein ganzes Stück und markiere vorher drei Atemstellen."}},

"recorder-9":{title:"Abschlussstück — Ode an die Freude",goal:"Ein vollständiges klassisches Werk spielen",b:{
0:"Ode an die Freude — Beethoven (gemeinfrei)",
1:"Die Blockflöte ist ein hervorragendes Tor zu anderen Blasinstrumenten: Querflöte, Klarinette, Saxofon. Atmung und Zungenstoß übertragen sich fast unverändert.",
2:{q:"Welches Instrument gilt als natürliche Fortsetzung nach der Blockflöte?",o:["Schlagzeug","Querflöte oder Klarinette","Klavier","Geige"],w:"Die Atem- und Zungentechnik überträgt sich direkt auf Holzblasinstrumente."},
3:"Spiele das Stück von Anfang bis Ende ohne anzuhalten."}},

/* ===================== SCHLAGZEUG ===================== */
"drums-1":{title:"Rhythmus — die Körpersprache der Musik",goal:"Einen gleichmäßigen Puls halten",b:{
0:"Für den Anfang braucht man kein Schlagzeug. Ein Tisch, zwei Hände oder zwei Stifte reichen für die ersten drei Lektionen völlig aus.",
1:"Viertelschläge — im Vierertakt zählen",
2:["Stelle das Metronom auf 72.","Klatsche genau auf jeden Schlag.","Zähle laut: 1-2-3-4.","Betone den ersten Schlag."],
3:"<b>Der Test:</b> Wenn du drängst oder schleppst, hörst du das Metronom „wandern“. Bist du genau, verschwindet es fast unter deinem Klatschen.",
4:{q:"Woran erkennt man Genauigkeit mit dem Metronom?",o:["Das Metronom klingt lauter","Das Metronom verschwindet fast unter deinem Klang","Du spielst schnell","Man kann es nicht erkennen"],w:"Wenn dein Schlag genau auf den Klick fällt, verschmelzen beide Klänge."},
5:"Zwei Minuten genaues Klatschen bei 72."}},

"drums-2":{title:"Der Basis-Groove",goal:"Den Groove spielen, der in 80 % aller Songs steckt",b:{
0:"Der Basis-Groove hat drei Bestandteile: <b>Hi-Hat</b> (durchgehende Achtel), <b>Bassdrum</b> (Schläge 1 und 3), <b>Snare</b> (Schläge 2 und 4).",
1:null,
2:["Beginne nur mit der Hi-Hat: 1-und-2-und-3-und-4-und.","Ergänze die Bassdrum auf den Schlägen 1 und 3.","Ergänze die Snare auf den Schlägen 2 und 4.","Spiele alle drei zusammen — langsam."],
3:"Wenn eine Hand oder ein Fuß die anderen „umwirft“, senke das Tempo um 20 %. Tempo ist ein Ergebnis, kein Ziel.",
4:{q:"Auf welche Schläge fällt die Snare im Basis-Groove?",o:["1 und 3","2 und 4","Auf alle Schläge","Nur auf 1"],w:"Die Snare auf 2 und 4 ist der „Backbeat“ — der Puls von Rock und Pop."},
5:"Spiele den Groove 16 Takte am Stück bei 70."}},

"drums-3":{title:"Unabhängigkeit der Gliedmaßen",goal:"Hände und Füße trennen",b:{
0:"Unabhängigkeit ist die Fähigkeit, dass jedes Glied gleichzeitig etwas anderes tut. Das wird gelernt — niemand wird damit geboren.",
1:["Spiele nur Hi-Hat und Snare.","Nur Hi-Hat und Bassdrum.","Nur Bassdrum und Snare.","Füge alle drei zusammen.","Verschiebe die Bassdrum auf das „4-und“ — und spüre, wie das Gehirn sich wehrt. Genau das ist das Training."],
2:"Unabhängigkeitsübung",
3:"Übe Unabhängigkeit 5 Minuten täglich — besser als eine Stunde einmal pro Woche. Es ist motorisches Lernen und braucht verteilte Wiederholungen.",
4:{q:"Wie entwickelt man Unabhängigkeit wirksam?",o:["Schnell spielen","In Gliedmaßenpaare zerlegen und schrittweise zusammenfügen","Ganze Songs spielen","Musik hören"],w:"Das Zerlegen in Paare lässt das Gehirn das Muster Schritt für Schritt aufbauen."},
5:"Übe drei Gliedmaßenpaare, je eine Minute."}},

"drums-4":{title:"Fills — der Übergang zwischen Teilen",goal:"Ein Fill über einen Takt spielen",b:{
0:"Ein <b>Fill</b> ist eine kurze Passage, die den Übergang zwischen Songteilen markiert. Das Basis-Fill: vier Achtelpaare auf Snare und Toms.",
1:"Ein Fill über einen Takt",
2:"Die wichtigste Regel eines Fills: <b>rechtzeitig zurückkommen</b>. Ein beeindruckendes Fill, das zu spät landet, ist schlechter als ein einfaches, das genau sitzt.",
3:{q:"Was ist bei einem Fill am wichtigsten?",o:["Dass es schnell ist","Dass es genau rechtzeitig zum Schlag 1 endet","Dass es lang ist","Dass alle Trommeln vorkommen"],w:"Das Fill dient dem Song — die Genauigkeit der Rückkehr zählt mehr als der Inhalt."},
4:"Spiele 4 Takte Groove + einen Takt Fill, viermal."}},

"drums-5":{title:"Dynamik und Gewicht",goal:"Die Kraft der Schläge steuern",b:{
0:"Ein guter Schlagzeuger schlägt nicht hart — er schlägt <b>richtig</b>. Ein guter Groove enthält mindestens drei Lautstärkestufen.",
1:["Hi-Hat — leise und gleichmäßig.","Bassdrum — mittel, im Bauch spürbar.","Snare — laut und scharf; das ist, was man hört.","Spiele denselben Groove einmal bei 30 % und dann bei 90 % Lautstärke."],
2:"Die Lautstärkekontrolle kommt aus dem Griff: ein lockerer Halt mit einem „Drehpunkt“ zwischen Daumen und Finger ergibt einen freien, federnden Schlag.",
3:{q:"Welches Element des Grooves soll am lautesten sein?",o:["Die Hi-Hat","Die Snare","Alles gleich laut","Die Bassdrum"],w:"Die Snare ist der „Klick“ des Grooves und tritt daher hervor."},
4:"Spiele den Groove in drei verschiedenen Lautstärkestufen."}},

"drums-6":{title:"Grooves in verschiedenen Stilen",goal:"Vier Grooves kennen",b:{
0:"Rock",1:"Shuffle / Blues",2:"Walzer",3:"Funk (Sechzehntel)",
4:"Stil ist nicht nur ein Muster — er ist auch ein Gefühl. Der Shuffle schwingt, Rock ist gerade, Funk ist scharf und abgehackt.",
5:{q:"Was unterscheidet rhythmische Stile voneinander?",o:["Nur das Tempo","Das Schlagmuster und das Gefühl (gerade oder swingend)","Die Art der Trommeln","Die Spiellautstärke"],w:"Muster und „Groove-Feeling“ definieren den Stil."},
6:"Spiele jeden der vier Grooves über 8 Takte."}},

"drums-7":{title:"Schlagzeugnoten lesen",goal:"Ein Groove-Schema entschlüsseln",b:{
0:"Die Schlagzeugnotation nutzt dasselbe Notensystem, aber jede Linie steht für eine andere Trommel: Hi-Hat oben (X), Snare in der Mitte, Bassdrum unten.",
1:["Oberste Linie mit einem X — Hi-Hat.","Der dritte Zwischenraum — Snare.","Der unterste Zwischenraum — Bassdrum.","Zähle den Takt: 1 und 2 und 3 und 4 und, und markiere, was wohin fällt."],
2:{q:"Was bedeutet ein X in der Schlagzeugnotation?",o:["Bassdrum","Ein Becken oder die Hi-Hat","Snare","Eine Pause"],w:"Ein X-förmiger Notenkopf steht für ein Metallinstrument — Hi-Hat, Crash oder Ride."},
3:"Schreibe den Basis-Groove auf Papier in Notenschrift."}},

"drums-8":{title:"Zu einem Song spielen",goal:"Den Takt gemeinsam mit Musik halten",b:{
0:"Der Schlagzeuger ist die Uhr der Band. Der Einstieg: Schlag 1 finden, einen ganzen Takt zählen und einsteigen.",
1:["Höre den Song und finde den Backbeat (2 und 4).","Klatsche 30 Sekunden dazu.","Spiele den Basis-Groove über den Song.","Ergänze nach jeweils 8 Takten ein Fill."],
2:"Fülle nicht jede Sekunde. Die Pausen des Schlagzeugers zählen genauso viel wie die Schläge.",
3:{q:"Was ist die zentrale Rolle des Schlagzeugers in einer Band?",o:["Am lautesten zu sein","Ein stabiles Tempo halten und Übergänge führen","Soli spielen","Akkorde wechseln"],w:"Die Stabilität des Tempos ist das Fundament, auf das sich die ganze Band stützt."},
4:"Spiele 3 Minuten lang zu einem Song, den du magst."}},

"drums-9":{title:"Abschluss und Ausblick",goal:"Groove, Fills und Dynamik verbinden",b:{
0:"Du hast die Grundlagen abgeschlossen: Groove, Unabhängigkeit, Fills, Dynamik und Stile.",
1:["Spiele 8 Takte Rock-Groove.","Ein Fill über einen Takt.","8 Takte Shuffle.","Ein Fill.","Schließe mit einem Crash auf Schlag 1."],
2:"Die nächste Stufe: Rudiments (Paradiddle, Ruff, Doppelschlagwirbel) — das sind die „Tonleitern“ des Schlagzeugers.",
3:{q:"Was sind Rudiments?",o:["Trommelarten","Grundlegende Schlagmuster, aus denen alles aufgebaut ist","Lateinamerikanische Rhythmen","Stockarten"],w:"Rudiments sind die Bausteine der Schlagzeugtechnik."},
4:"Nimm dich beim Spielen einer vollständigen Abfolge auf."}},

/* ===================== BASS ===================== */
"bass-1":{title:"Den Bass kennenlernen",goal:"Leere Saiten im Takt spielen",b:{
0:"Der E-Bass ist die Brücke zwischen Schlagzeug und Gitarre. Vier Saiten: <b>E-A-D-G</b>, eine Oktave unter den vier dicken Gitarrensaiten.",
1:"Die leeren Saiten",
2:["Rechte Hand: Zeige- und Mittelfinger wechseln sich ab — die „Zwei-Finger-Technik“.","Der Daumen ruht auf dem Tonabnehmer.","Linke Hand: ein Finger pro Bund.","Spiele jede leere Saite viermal."],
3:"<b>Die erste Regel des Bassisten:</b> Ein sauberer, kurzer Ton an der richtigen Stelle ist mehr wert als zehn beeindruckende.",
4:{q:"Wie lautet die Standardstimmung eines viersaitigen Basses?",o:["G-C-E-A","E-A-D-G","E-A-D-G-B-E","D-A-D-G"],w:"E-A-D-G — wie die vier dicken Gitarrensaiten, eine Oktave tiefer."},
5:"Spiele auf jeder leeren Saite 8 Schläge mit dem Metronom auf 70."}},

"bass-2":{title:"Deine erste Basslinie",goal:"Den Grundton jedes Akkords spielen",b:{
0:"Die Grundaufgabe des Bassisten: den <b>Grundton</b> des Akkords spielen, den die Gitarre spielt, auf dem ersten Schlag jedes Takts.",
1:"Basslinie für die Folge G-C-D",
2:["Akkord G → spiele G.","Akkord C → spiele C.","Akkord D → spiele D.","Ein langer Schlag pro Takt, danach vier Viertel."],
3:"Ein guter Bassist weiß ohne Nachdenken, wo jeder Ton liegt. Übe: „Wo ist F?“ und finde es an drei verschiedenen Stellen.",
4:{q:"Was ist der Grundton?",o:["Der höchste Ton des Akkords","Der Ton, der dem Akkord seinen Namen gibt","Der erste Ton der Tonleiter","Die dicke Saite"],w:"Beim G-Akkord ist der Grundton G. Das ist der Basiston des Bassisten."},
5:"Spiele die Grundtöne der Folge G-C-D-G, je vier Schläge."}},

"bass-3":{title:"Rhythmus und Groove mit dem Schlagzeug",goal:"Den Bass mit der Bassdrum verzahnen",b:{
0:"Die Magie einer Band entsteht, wenn Bass und Bassdrum <b>exakt zusammen</b> spielen. Das nennt man „Lock“.",
1:"Bassdrum-Muster zum Mitüben",
2:["Höre das Bassdrum-Muster.","Spiele genau auf jeden Schlag einen Ton.","Füge keine Töne hinzu — sei nur genau.","Ergänze nun einen Durchgangston vor dem nächsten Takt."],
3:"Wenn du zwischen den Schlägen spielst und unsicher bist — spiele nicht. Eine genaue Pause ist besser als ein ungenauer Ton.",
4:{q:"Mit welchem Instrument muss der Bass am stärksten synchron sein?",o:["Mit der Gitarre","Mit der Bassdrum","Mit dem Gesang","Mit dem Klavier"],w:"Das Duo Bass + Bassdrum ist die rhythmische Grundlage jeder Besetzung."},
5:"Spiele zwei Minuten lang zum Bassdrum-Muster."}},

"bass-4":{title:"Töne auf dem Griffbrett",goal:"Jeden Ton an zwei Stellen finden",b:{
0:"Auf der E-Saite: Bund 1 = F, Bund 3 = G, Bund 5 = A. Auf der A-Saite: Bund 2 = H, Bund 3 = C.",
1:"<b>Die Oktavregel:</b> Derselbe Ton liegt auch zwei Saiten tiefer und zwei Bünde weiter. Das ist die nützlichste Abkürzung auf dem Bass.",
2:"Derselbe Ton in zwei Oktaven",
3:{q:"Wo liegt die Oktave eines Tons auf dem Bass?",o:["Auf derselben Saite 12 Bünde höher, oder zwei Saiten tiefer und zwei Bünde weiter","Im selben Bund auf der Nachbarsaite","Es gibt keine feste Regel","Drei Bünde zurück"],w:"Beides ist richtig, und das „Zwei-und-Zwei“-Muster ist im Alltag das schnellste."},
4:"Wähle einen Ton und finde ihn an drei verschiedenen Stellen des Griffbretts."}},

"bass-5":{title:"Walking Bass",goal:"Akkorde mit Durchgangstönen verbinden",b:{
0:"<b>Walking Bass</b> — eine Basslinie, die vier Töne pro Takt spielt und schrittweise von Akkord zu Akkord führt.",
1:"Eine einfache Walking Line",
2:["Beginne auf dem Grundton.","Spiele Töne aus dem Akkord (Grundton, Terz, Quinte).","Erreiche einen Ton, der einen Schritt vom nächsten Grundton entfernt liegt.","Lande auf dem nächsten Grundton auf Schlag 1."],
3:{q:"Wozu dient ein Durchgangston in einer Walking-Bass-Linie?",o:["Um Platz zu füllen","Um sanft zum Grundton des nächsten Akkords zu führen","Damit es schnell klingt","Um das Schlagzeug zu ersetzen"],w:"Ein Durchgangston erzeugt Erwartung und einen natürlichen Zug zum nächsten Akkord."},
4:"Spiele eine Walking Line über die Folge C-F-G-C."}},

"bass-6":{title:"Techniken der rechten Hand",goal:"Finger, Plektrum und Slap kennenlernen",b:{
0:["<b>Fingerstyle:</b> der wärmste und häufigste Klang.","<b>Plektrum:</b> ein scharfer, durchsetzungsfähiger Klang, gut für Rock und Punk.","<b>Slap:</b> Der Daumen schlägt die dicke Saite, der Finger „zupft“ die dünne heraus — der typische Funk-Sound."],
1:"Basis-Slap-Muster",
2:"Beim Slap dreht sich der Daumen um eine Achse — er „sticht“ nicht. Das Zurückfedern gehört zur Bewegung.",
3:{q:"Was ist die Slap-Technik?",o:["Spiel mit Plektrum","Ein Daumenschlag und ein Fingerzupfer","Spiel mit beiden Händen","Saiten abdämpfen"],w:"Die Kombination aus Daumenschlag und Fingerzupfer erzeugt den perkussiven Klang."},
4:"Spiele acht Takte in jeder der Techniken."}},

"bass-7":{title:"Abdämpfen und Geräuschkontrolle",goal:"Sauber spielen, ohne klingende Saiten",b:{
0:"Das Problem Nummer eins am Bass sind nicht falsche Töne — es ist das <b>Geräusch</b>: Saiten, die weiterschwingen.",
1:["Der Daumen der rechten Hand ruht auf der dicken Saite und dämpft sie.","Die Finger der linken Hand, die nicht spielen, berühren leicht die Nachbarsaiten.","Denke nach jedem Ton daran, wie du ihn <b>beendest</b>, nicht nur, wie du ihn beginnst.","Spiele einen Ton, dämpfe ihn vollständig ab und spiele erst dann den nächsten."],
2:{q:"Was ist das häufigste Problem beim Bassspiel?",o:["Falsche Töne","Geräusche von nicht abgedämpften Saiten","Langsames Tempo","Dünne Saiten"],w:"Geräuschkontrolle ist der Unterschied zwischen Amateur und Profi."},
3:"Spiele eine Minute lang Ton-Stille-Ton-Stille."}},

"bass-8":{title:"Eine Basslinie für einen ganzen Song",goal:"Eine eigenständige Basslinie bauen",b:{
0:"Eine gute Basslinie entsteht in drei Schritten: nur Grundtöne → Grundtöne im Rhythmus → Durchgangstöne und Variation ergänzen.",
1:"Blues-Riff (Originalübung)",
2:"Höre den Bassisten in deinen Lieblingssongs zu. Achte darauf, wie wenig sie spielen — und wie richtig es sich anfühlt.",
3:{q:"Wie lautet die richtige Reihenfolge beim Bau einer Basslinie?",o:["Sofort improvisieren","Grundtöne → Rhythmus → Durchgangstöne","Ein Solo kopieren","Beim höchsten Ton beginnen"],w:"Der schrittweise Aufbau hält die Linie stabil und im Dienst des Songs."},
4:"Baue eine Basslinie zu einem Song, den du kennst, in den drei Schritten."}},

"bass-9":{title:"Abschluss und Ausblick",goal:"In einer Band spielen",b:{
0:"Du hast die Grundlagen abgeschlossen. Ein Bassist mit stabilem Timing, sauberem Klang und harmonischem Verständnis wird in jeder Band gesucht.",
1:["Übe täglich mit Metronom, auch nur 5 Minuten.","Nimm dich auf — das Ohr bemerkt, was die Hand nicht spürt.","Spiele so bald wie möglich mit anderen Menschen.","Lerne die Dur-Tonleiter und das natürliche Moll über das ganze Griffbrett."],
2:{q:"Welche Eigenschaft ist bei einem Bassisten am wichtigsten?",o:["Geschwindigkeit","Stabiles Timing und sauberer Klang","Notenkenntnis","Teures Equipment"],w:"Stabilität ist das, was die ganze Band gut klingen lässt."},
3:"Spiele einen ganzen Song von Anfang bis Ende mit Metronom."}}

});

/* ---- die vier neuen Instrumente ---- */
I18N.registerLessons("de", {

"violin-1":{title:"Haltung und leere Saiten",goal:"Auf allen vier Saiten einen sauberen Ton erzeugen",b:{
0:"Die Geige ist das Instrument, bei dem <b>das Ohr den Finger führt</b>. Es gibt keine Bünde, jeder Ton entsteht also durch Hören — und genau das macht sie zur besten Lehrerin für das Gehör.",
1:"Vier Saiten, von der dicksten zur dünnsten: <b>G, D, A, E</b>. Zwischen je zwei liegt eine Quinte.",
3:["Lege die Geige auf das Schlüsselbein, das Kinn auf den Kinnhalter.","Die linke Hand hält den Hals locker — sie umklammert ihn nicht.","Der Bogen liegt auf der Saite, in der Mitte zwischen Steg und Griffbrett.","Ziehe den Bogen langsam und mit gleichmäßigem Druck. Ein sauberer Ton zählt mehr als ein lauter."],
4:"Ein Pfeifen? Eine von drei Ursachen: ungleicher Druck, der Bogen zu weit vom Steg, oder wechselnde Geschwindigkeit. Werde langsamer.",
5:{q:"Wie sind die Saiten der Geige gestimmt?",o:["In Quarten","In Quinten","In Oktaven","In Terzen"],w:"G-D-A-E — eine Quinte zwischen je zwei benachbarten Saiten."},
6:"Spiele jede leere Saite achtmal mit ganzem Bogen, ohne Pfeifen."}},

"violin-2":{title:"Der erste Finger",goal:"Vier neue Töne spielen",b:{
0:"Der erste Finger setzt einen <b>Ganzton</b> von der leeren Saite entfernt auf. Das ist der Ankerpunkt der ganzen Hand.",
2:"Klebe ein Stückchen Klebeband dorthin, wo der erste Finger landet. Das ist kein Schummeln — so lernen alle Geigerinnen und Geiger der Welt im ersten Jahr.",
3:"Leere Saite und erster Finger",
4:{q:"Wie groß ist der Abstand von der leeren Saite zum ersten Finger?",o:["Ein Halbton","Ein Ganzton","Anderthalb Töne","Zwei Töne"],w:"Ein Ganzton — und das ist der erste Abstand, den das Ohr lernt."},
5:"Spiele die Übung langsam und prüfe jeden Ton mit dem Stimmgerät in der App."}},

"violin-3":{title:"Eine erste Melodie",goal:"Ein ganzes Stück auf zwei Saiten spielen",b:{
0:"Mit den leeren Saiten und dem ersten Finger kannst du bereits eine echte Melodie spielen.",
2:"Übung auf zwei Saiten",
3:"<b>Die Regel des ersten Jahres:</b> langsam und sauber schlägt schnell und schlampig — immer.",
4:{q:"Worauf kommt es in dieser Phase am meisten an?",o:["Schnell spielen, um voranzukommen","Langsam spielen und jedem Ton zuhören","Schwere Töne überspringen","So laut wie möglich spielen"],w:"Auf der Geige hört man jede Ungenauigkeit sofort. Langsamer zu werden ist die Abkürzung."},
5:"Spiele die Melodie fünfmal, jedes Mal ein wenig schneller."}},

"violin-4":{title:"Drei Finger — deine erste Tonleiter",goal:"D-Dur über zwei Saiten spielen",b:{
0:"Auf der Geige entsteht eine Tonleiter nicht aus Bünden, sondern aus einem <b>festen Fingermuster</b>. Hat die Hand es einmal gelernt, wiederholt es sich auf jeder Saite.",
1:"Auf der D-Saite: Finger 1 = E, Finger 2 = Fis, Finger 3 = G. Achte darauf, dass Finger 2 und 3 <b>einander berühren</b> — das ist das Zeichen, dass das Muster stimmt.",
3:"D-Dur-Tonleiter",
4:"In einer Durtonleiter liegen Finger 2 und 3 dicht beieinander. Öffnet sich eine Lücke, wird das Fis zu tief.",
5:{q:"Was kennzeichnet die Lage von Finger 2 und 3 in Dur?",o:["Ein großer Abstand","Sie berühren einander","Finger 3 wird nicht gebraucht","Es gibt keine feste Regel"],w:"Ihre Nähe ist der Halbton zwischen der dritten und vierten Stufe."},
6:"Spiele die Tonleiter zehnmal auf und ab, langsam, und prüfe jeden Ton mit dem Stimmgerät."}},

"violin-5":{title:"Bogeneinteilung",goal:"Länge und Stärke des Tons steuern",b:{
0:"Der Bogen ist der <b>Atem</b> der Geige. Ein langer Ton braucht einen langsamen Bogen, ein kurzer wenig Bogen — und der Druck bleibt gleich.",
1:["Markiere dir drei Bereiche: Frosch, Mitte, Spitze.","Spiele eine ganze Note mit ganzem Bogen, vom Frosch bis zur Spitze, in vier Sekunden.","Spiele vier Viertel in demselben Bogen — jedes ein Viertel der Strecke.","Spiele nun Achtel nur in der Bogenmitte."],
2:"Bogeneinteilung",
3:"Wird der Ton zur Spitze hin schwächer? Der Druck sinkt mit deinem Arm. Halte ihn bis zur Spitze gleichmäßig.",
4:{q:"Was bestimmt die Länge eines Tons auf der Geige?",o:["Der Fingerdruck","Die Bogengeschwindigkeit","Wie man das Instrument hält","Die Saitenstärke"],w:"Die Bogengeschwindigkeit bestimmt die Länge, der Druck die Lautstärke."},
5:"Spiele eine ganze Tonleiter mit ganzem Bogen pro Ton, danach mit halbem Bogen."}},

"violin-6":{title:"Zweite Saite und Saitenwechsel",goal:"Ohne Nebengeräusche zwischen Saiten wechseln",b:{
0:"Der Saitenwechsel ist die Stelle, an der man den Unterschied zwischen Anfänger und Spieler hört. Das Geheimnis: <b>der Arm setzt sich in Bewegung, bevor der Ton wechselt</b>.",
2:"Wechselübung",
3:"Klingt beim Wechsel ein Doppelton, hat der Bogen zwei Saiten berührt. Ändern muss sich der Winkel, nicht der Druck.",
4:{q:"Wodurch entsteht beim Saitenwechsel ein Doppelton?",o:["Zu viel Druck","Der Bogen berührt zwei Saiten","Das Instrument ist verstimmt","Der Finger liegt falsch"],w:"Es ist der Bogenwinkel, der die Saiten trennt."},
5:"Spiele die Wechselübung zehnmal, vollkommen sauber."}},

"violin-7":{title:"Ein erstes Vibrato",goal:"Die Vibratobewegung kennenlernen",b:{
0:"Vibrato ist ein <b>kleines Wiegen des Fingers</b>, das den Ton wärmt. Es wird später unterrichtet, als man denkt — und das mit Absicht: es verdeckt Ungenauigkeit, also lernt man zuerst, ohne es sauber zu spielen.",
1:["Setze Finger 2 auf die A-Saite, ohne Bogen.","Wiege die Hand aus dem Handgelenk vor und zurück, nicht aus dem Finger.","Der Finger bleibt liegen — nur die Tonhöhe ändert sich leicht.","Nimm den Bogen erst dazu, wenn die Bewegung fließt."],
2:"Ein schnelles, enges Vibrato klingt wie Zittern. Ein langsames, weites klingt wie Gesang. Fang langsam an.",
3:{q:"Woher kommt die Vibratobewegung?",o:["Aus dem Finger","Aus dem Handgelenk","Nur aus dem Ellbogen","Aus der Schulter"],w:"Die Bewegung kommt aus dem Handgelenk; der Finger geht nur mit."},
4:"Übe die Bewegung eine Minute ohne Bogen, danach eine Minute mit Bogen."}},

"violin-8":{title:"Eine vollständige Melodie",goal:"Ein bekanntes Stück von Anfang bis Ende spielen",b:{
0:"Jetzt fügt sich alles zusammen: das Fingermuster, die Bogeneinteilung und die Saitenwechsel.",
1:"Melodie für zwei Saiten",
2:"Spiele zuerst ohne Bogen — nur gezupft — um zu prüfen, ob die Finger sitzen. Dann nimm den Bogen dazu.",
3:{q:"Was sollte man prüfen, bevor man den Bogen dazunimmt?",o:["Die Lautstärke","Dass die Finger richtig liegen","Das Tempo","Die Kopfhaltung"],w:"Zupfen isoliert die linke Hand und deckt Ungenauigkeiten sofort auf."},
4:"Spiele die Melodie fünfmal — zweimal gezupft und dreimal gestrichen."}},

"violin-9":{title:"Rückblick und Ausblick",goal:"Sicher spielen und wissen, wie es weitergeht",b:{
0:"Du hast die Grundlagen abgeschlossen: Haltung, leere Saiten, Fingermuster, Bogeneinteilung und Saitenwechsel. Alles Weitere baut darauf auf.",
1:"Wie es weitergeht: <b>zweite Lage</b> (die ganze Hand den Hals hinaufschieben), <b>Spiel auf zwei Saiten gleichzeitig</b> und <b>Notenlesen</b> während des Spielens.",
2:"Abschlussstück",
3:"<b>Der klassische Fehler im zweiten Jahr:</b> schneller werden, bevor der Ton sauber ist. Spiele alles mit langsamem Metronom — und du überholst die, die geeilt sind.",
4:{q:"Was ist der natürliche nächste Schritt auf der Geige?",o:["Schneller spielen","Zweite Lage und Notenlesen","Das Instrument wechseln","Auf den Bogen verzichten"],w:"Die zweite Lage öffnet den restlichen Hals, das Notenlesen das Repertoire."},
5:"Spiele das Abschlussstück und nimm dich auf. Sich selbst zuzuhören ist die ehrlichste Lehrerin."}},

"harmonica-1":{title:"Blasen und ziehen",goal:"Aus einem einzelnen Kanal einen sauberen Ton erzeugen",b:{
0:"Die Mundharmonika ist das einzige Instrument, bei dem <b>Blasen und Ziehen beide einen Ton erzeugen</b> — und zwar zwei verschiedene aus demselben Kanal.",
1:"Eine Mundharmonika in C hat zehn Kanäle und zwanzig Stimmzungen. Der vierte Kanal ist der Ausgangspunkt fast jeder Melodie.",
3:["Halte die Mundharmonika zwischen Daumen und Zeigefinger, die Zahlen nach oben.","Spitze die Lippen, als würdest du „u“ sagen.","Blase sanft in Kanal vier — das ist C.","Zieh nun aus demselben Kanal — das ist D."],
4:"Es klingen mehrere Töne gleichzeitig? Dein Mund ist zu weit offen. Verenge die Lippen, bis nur ein sauberer Ton bleibt.",
5:{q:"Was unterscheidet die Mundharmonika von anderen Blasinstrumenten?",o:["Sie hat keine hohen Töne","Blasen und Ziehen erzeugen beide einen Ton","Sie muss jedes Mal gestimmt werden","Man muss Knöpfe drücken"],w:"In jedem Kanal sitzen zwei Stimmzungen — eine zum Blasen, eine zum Ziehen."},
6:"Wechsle auf Kanal 4 zwanzigmal zwischen Blasen und Ziehen, mit sauberem Ton."}},

"harmonica-2":{title:"Vier Kanäle — deine erste Melodie",goal:"Eine bekannte Melodie spielen",b:{
0:"Die Kanäle 4 bis 7 enthalten eine vollständige C-Dur-Tonleiter. Dort lebt fast jedes Volkslied.",
2:"Sieh dir den Pfeil über der Grafik an: nach oben heißt blasen, nach unten ziehen. Mehr musst du dir nicht merken.",
3:"Die Tonleiter auf der Mundharmonika",
4:{q:"In welchen Kanälen liegt eine vollständige C-Dur-Tonleiter?",o:["1 bis 4","4 bis 7","7 bis 10","In allen"],w:"Nur in den Kanälen 4 bis 7 ist die Tonleiter ohne Bending vollständig."},
5:"Spiele die Tonleiter zehnmal auf und ab."}},

"harmonica-3":{title:"Dein erstes Lied",goal:"Eine ganze Melodie auswendig spielen",b:{
0:"Jetzt fügt sich alles zusammen. Diese Melodie nutzt nur die Kanäle 4 bis 6.",
2:"Melodie für vier Kanäle",
3:"Versuch zu spielen, ohne auf die Zahlen zu sehen. Auf der Mundharmonika findet das Ohr den Kanal schneller als das Auge.",
4:{q:"Wie lernt man eine Melodie auf der Mundharmonika am besten?",o:["Die Kanalnummern auswendig lernen","Hinhören und nach Gehör suchen","Atemzüge zählen","Noten lesen"],w:"Die Mundharmonika wurde fürs Spielen nach Gehör gebaut — das ist ihre Stärke."},
5:"Spiele die Melodie dreimal mit geschlossenen Augen."}},

"harmonica-4":{title:"Einen einzelnen Kanal spielen",goal:"Einen sauberen Einzelton ohne Nachbarn erzeugen",b:{
0:"Bisher klangen vielleicht mehrere Töne zugleich. Jetzt lernst du, <b>nur einen</b> herauszuholen — und genau das macht aus Lärm eine Melodie.",
1:["Nimm die Mundharmonika tiefer zwischen die Lippen, als würdest du trinken.","Die Zunge liegt unten und entspannt.","Verenge die Lippenöffnung, bis ein einzelner Ton klingt.","Prüfe es: blase in Kanal 4 — hörst du einen Akkord, sind die Lippen zu weit."],
3:"Eine zweite Methode, das <b>Zungenblocken</b>: Bedecke drei Kanäle mit dem Mund und blockiere zwei davon mit der Zunge. Einer bleibt offen.",
4:{q:"Warum klingen mehrere Töne gleichzeitig?",o:["Die Mundharmonika ist kaputt","Die Lippenöffnung ist zu weit","Du bläst zu kräftig","Die Kanäle sind verstopft"],w:"Ein weiter Mund bedeckt mehrere Kanäle auf einmal."},
5:"Spiele die Kanäle 4, 5 und 6 blasend — jeden einzeln und sauber, zwanzigmal."}},

"harmonica-5":{title:"Die zweite Oktave",goal:"Den Umfang auf die Kanäle 1 bis 7 erweitern",b:{
0:"Die tiefen Kanäle (1–3) geben die vollen Töne, die hohen (7–10) die schneidenden. Die meisten Melodien leben in der Mitte.",
2:"Achte auf eine Merkwürdigkeit: ab Kanal 7 ist <b>der Zugton tiefer als der Blaston</b> — umgekehrt als bei den tiefen Kanälen. Das ist eine Eigenschaft der Stimmung, kein Defekt.",
3:"Voller Umfang",
4:{q:"Was ändert sich ab Kanal 7?",o:["Nichts","Der Zugton wird tiefer als der Blaston","Man kann nicht mehr ziehen","Der Ton ist schwächer"],w:"Das ist eine eingebaute Umkehrung der Richter-Stimmung."},
5:"Spiele alle Blastöne von Kanal 1 bis 10 und zurück."}},

"harmonica-6":{title:"Rhythmus und Atmung",goal:"Im Takt spielen, ohne außer Atem zu geraten",b:{
0:"Auf der Mundharmonika ist der Atem zugleich Klang und Treibstoff. Spielst du zu lange in eine Richtung, geht dir die Luft aus.",
1:"Blasen und Ziehen im Wechsel",
2:"<b>Die Regel:</b> Verlangt die Melodie drei Blastöne hintereinander, suche eine Stelle zum Richtungswechsel. Meist gibt es denselben Ton in einem anderen Kanal.",
3:"Atemübung",
4:{q:"Was tust du, wenn dir mitten in einer Phrase die Luft ausgeht?",o:["Kräftiger blasen","Eine Stelle zum Richtungswechsel suchen","Aufhören zu spielen","Schneller spielen"],w:"Der Richtungswechsel ist die Atmung der Mundharmonika."},
5:"Spiele die Übung zwei Minuten am Stück, ohne außer Atem zu kommen."}},

"harmonica-7":{title:"Akkorde und Tremolo",goal:"Mehrere Kanäle bewusst zusammen nutzen",b:{
0:"Bisher haben wir gegen die Nachbartöne gekämpft. Jetzt <b>nutzen wir sie bewusst</b>: mehrere Kanäle zusammen ergeben einen vollen Akkord.",
1:"Blasen in die Kanäle 1–4 ergibt einen C-Dur-Akkord. Ziehen in die Kanäle 1–4 ergibt einen G-Akkord.",
2:"<b>Tremolo:</b> Bewege die Hand, die die Mundharmonika hält, vor dem Mund. Der Ton beginnt zu wogen und erinnert an einen Zug.",
3:"Akkordbegleitung",
4:{q:"Welcher Akkord entsteht beim Blasen in die Kanäle 1 bis 4?",o:["G-Dur","C-Dur","a-Moll","D-Dur"],w:"Die Blastöne sind aus den Tönen des C-Akkords gebaut — C, E und G."},
5:"Spiele zwei Minuten lang eine Akkordbegleitung zu einem Lied, das du kennst."}},

"harmonica-8":{title:"Ein ganzes Lied",goal:"Eine bekannte Melodie von Anfang bis Ende spielen",b:{
0:"Jetzt fügt sich alles zusammen: Einzelton, Rhythmus und geplante Atmung.",
2:"Vollständige Melodie",
3:"Markiere dir vorher, wo du bläst und wo du ziehst. Vorausplanen erspart dir die Atemnot.",
4:{q:"Was hilft gegen Atemnot?",o:["Leise spielen","Vorher planen, wann geblasen und wann gezogen wird","Schnell spielen","Das Lied kürzen"],w:"Die Luftrichtung zu planen ist die Kernfähigkeit auf der Mundharmonika."},
5:"Spiele die Melodie fünfmal hintereinander ohne Pause."}},

"harmonica-9":{title:"Rückblick und Ausblick",goal:"Wissen, was du gelernt hast und wie es weitergeht",b:{
0:"Du hast die Grundlagen abgeschlossen: Blasen und Ziehen, Einzelton, voller Umfang, Rhythmus, Akkorde und ein ganzes Lied.",
1:"Wie es weitergeht: <b>Bending</b> — die Tonhöhe mit der Zunge verändern, wodurch sich die Töne spielen lassen, die nicht in der Stimmung liegen. Genau das gibt der Mundharmonika ihren Blues-Klang.",
2:"Abschlussstück",
3:"Bending braucht Monate, nicht Tage. Übe es nicht, bevor deine Einzeltöne vollkommen sauber sind.",
4:{q:"Was macht Bending möglich?",o:["Eine andere Mundharmonika","Die Form von Mund und Zunge zu verändern","Kräftig blasen","Die Stimmzungen tauschen"],w:"Die Form des Mundraums verändert die Tonhöhe."},
5:"Spiele das Abschlussstück und nimm dich auf."}},

"glock-1":{title:"Der erste Schlag",goal:"Einen sauberen Ton erzeugen und den Aufbau verstehen",b:{
0:"Das Glockenspiel ist das einfachste Melodieinstrument für den Anfang: <b>nichts zu stimmen, kein Fingersatz und kein Atem</b>. Du schlägst an — und der richtige Ton erklingt.",
1:"Die Platten sind genau wie Klaviertasten angeordnet: eine lange Reihe weißer, darüber Gruppen aus zwei und drei.",
2:"Schlag die markierte Platte an — das ist C",
3:["Halte den Schlägel locker, zwischen Daumen und Zeigefinger.","Triff die Mitte der Platte — nicht das Ende.","Hebe den Schlägel sofort nach dem Schlag. Ein liegen bleibender Schlägel erstickt den Ton.","Ein leichter Schlag genügt. Das Instrument erledigt den Rest."],
4:"Dumpfer Klang? Der Schlägel bleibt auf der Platte liegen. Denk an Abprallen, nicht an Drücken.",
5:{q:"Wo schlägt man die Platte an?",o:["Am Ende","In der Mitte","Nahe der Schraube","Das ist egal"],w:"Die Mitte gibt den vollsten Ton. Die Enden klingen dumpf."},
6:"Schlage jede weiße Platte einmal an, von unten nach oben, mit sauberem Ton."}},

"glock-2":{title:"Die Tonleiter und deine erste Melodie",goal:"Eine bekannte Melodie spielen",b:{
0:"Die C-Dur-Tonleiter sind schlicht alle weißen Platten hintereinander. Mehr braucht es für die erste Melodie nicht.",
1:"C-Dur-Tonleiter",
2:"Erste Melodie",
3:"<b>Hände abwechseln:</b> rechts-links-rechts-links. Das verdoppelt das Tempo ohne zusätzliche Mühe.",
4:{q:"Was bringt das Abwechseln der Hände?",o:["Einen lauteren Klang","Man spielt schneller ohne Mühe","Die Platten nutzen sich weniger ab","Es bringt nichts"],w:"Eine Hand muss zurück; zwei Hände wechseln ohne Unterbrechung."},
5:"Spiele die Melodie fünfmal mit abwechselnden Händen."}},

"glock-3":{title:"Rhythmus und Dynamik",goal:"In verschiedenen Stärken und im Takt spielen",b:{
0:"Auf dem Glockenspiel ist der Ton kurz, also sind <b>Zeit und Stärke</b> der ganze Ausdruck, den du hast. Genau das macht aus unauffälligem Spiel eindrucksvolles Spiel.",
1:"Grundrhythmus",
2:"Spiel dieselbe Melodie einmal kräftig und einmal zart. Der Unterschied ist größer, als man denkt.",
3:"Dieselbe Melodie, anderer Rhythmus",
4:{q:"Was schafft Ausdruck auf dem Glockenspiel?",o:["Die Tonlänge","Stärke und Zeit","Das Stimmen der Platten","Die Zahl der Schlägel"],w:"Der Ton ist kurz und unveränderlich — deine Mittel sind Lautstärke und Timing."},
5:"Spiele die Melodie dreimal: leise, mittel und laut."}},

"glock-4":{title:"Zwei Hände und Sprünge",goal:"Eine Passage mit Lagenwechseln spielen",b:{
0:"Auf dem Glockenspiel bleibt die Hand nicht stehen. <b>Das Auge führt — die Hand folgt</b>, und das lernt man gesondert.",
1:"Drei Ankerpunkte — C, G und hohes C",
2:["Finde die drei Ankerpunkte auf dem Instrument.","Schlage C an, dann G, ohne auf den Schlägel zu sehen.","Nimm das hohe C dazu.","Spiele nun alle drei nacheinander bei Metronom 60."],
3:"Sieh auf die <b>nächste</b> Platte, während du die aktuelle anschlägst. Das ist das Geheimnis jedes Mallet-Spielers.",
4:{q:"Wohin sieht man beim Spielen?",o:["Auf den Schlägel","Auf die nächste Platte","Nur in die Noten","Das ist egal"],w:"Der Blick eilt der Hand voraus, genau wie beim Lesen."},
5:"Spiele C-G-C zwanzigmal, ohne danebenzuschlagen."}},

"glock-5":{title:"Die oberen Platten",goal:"In einer Tonart mit Kreuz spielen",b:{
0:"Die oberen Platten sind die Halbtöne — genau wie die schwarzen Tasten am Klavier, und in denselben Gruppen aus zwei und drei.",
1:"G-Dur-Tonleiter — achte auf das Fis",
2:"Die oberen Platten sind schmaler. Ziele auf die Mitte, sonst rutscht der Schlägel ab.",
3:{q:"Wie sind die oberen Platten angeordnet?",o:["In einer gleichmäßigen Reihe","In Gruppen aus zwei und drei","Zufällig","Es gibt keine oberen Platten"],w:"Genau wie die schwarzen Tasten eines Klaviers."},
4:"Spiele die G-Dur-Tonleiter fünfmal auf und ab."}},

"glock-6":{title:"Komplexerer Rhythmus",goal:"Achtel und punktierte Noten spielen",b:{
0:"Der Ton auf dem Glockenspiel ist kurz, deshalb hört man <b>rhythmische Genauigkeit</b> sofort. Hier lernst du, den Schlag zu teilen.",
1:"Achtel",
2:"Melodie in Achteln",
3:"Zähle laut mit: „eins-und-zwei-und“. Lautes Zählen ist genauer als Zählen im Kopf.",
4:{q:"Was hilft der rhythmischen Genauigkeit?",o:["Laut spielen","Laut mitzählen","Schnell spielen","Auf die Hände sehen"],w:"Lautes Zählen verbindet den Körper mit der Zeit."},
5:"Spiele die Melodie bei Metronom 70, dann bei 85."}},

"glock-7":{title:"Zwei Stimmen",goal:"Melodie und Begleitung zugleich spielen",b:{
0:"Zwei Hände heißt zwei Stimmen. Eine Hand spielt die Melodie, die andere setzt einen Ankerton.",
1:"C-Akkord — die drei Töne zusammen",
2:"Melodie mit Anker",
3:"Beginne damit, dass die zweite Hand nur auf der ersten Zählzeit jedes Takts anschlägt. Das klingt schon voll.",
4:{q:"Wie fügt man am einfachsten eine zweite Stimme hinzu?",o:["Alles zweimal spielen","Ein Ankerton auf der ersten Zählzeit","Schneller spielen","Einen dritten Schlägel nehmen"],w:"Ein einziger Anker pro Takt erzeugt bereits das Gefühl einer Begleitung."},
5:"Spiele die Melodie fünfmal mit Anker."}},

"glock-8":{title:"Ein Vortragsstück",goal:"Ein ganzes Stück sicher spielen",b:{
0:"Jetzt kommt alles zusammen: Sprünge, obere Platten, Rhythmus und zwei Stimmen.",
1:"Vortragsstück",
2:"Übe das Stück in drei getrennten Abschnitten und füge sie erst danach zusammen. So lernen Profis.",
3:{q:"Wie lernt man ein langes Stück?",o:["Es immer wieder durchspielen","In Abschnitte teilen und dann zusammenfügen","Nur den Anfang spielen","Allmählich schneller werden"],w:"Das Aufteilen spart Zeit und verhindert, dass sich Fehler festsetzen."},
4:"Spiele das Stück dreimal hintereinander ohne Unterbrechung."}},

"glock-9":{title:"Rückblick und Ausblick",goal:"Wissen, was du gelernt hast und wie es weitergeht",b:{
0:"Du hast geschafft: den sauberen Schlag, die Tonleiter, Sprünge, die oberen Platten, Rhythmus und zwei Stimmen.",
1:"Wie es weitergeht: <b>Xylophon und Marimba</b> (Holzplatten, wärmerer Klang), <b>vier Schlägel</b> in zwei Händen und <b>Notenlesen</b> während des Spielens.",
2:"Abschlussstück",
3:"Das Glockenspiel ist ein hervorragendes Tor zu allen Mallet-Instrumenten. Das Können überträgt sich fast vollständig.",
4:{q:"Was unterscheidet Glockenspiel und Xylophon?",o:["Die Größe","Metallplatten gegenüber Holzplatten","Die Zahl der Platten","Die Stimmung"],w:"Metall klingt hell und lang, Holz warm und kurz."},
5:"Spiele das Abschlussstück und nimm dich auf."}},

"mandolin-1":{title:"Kennenlernen und leere Saiten",goal:"Einen sauberen Ton erzeugen und die Stimmung verstehen",b:{
0:"Die Mandoline ist <b>genau wie eine Geige gestimmt</b> — G, D, A, E — aber sie hat Bünde. Jeder Ton hat seinen festen Platz, und nichts muss nach Gehör gesucht werden.",
2:["Halte das Plektrum zwischen Daumen und Zeigefinger, nur an der Spitze.","Schlage abwechselnd ab- und aufwärts — das ist die Grundbewegung.","Linke Hand: direkt hinter dem Bund drücken, nicht darauf.","Spiele jedes leere Saitenpaar viermal."],
3:"Zu jedem Ton gehören zwei nebeneinanderliegende Saiten. Das gibt der Mandoline ihren klingelnden Klang.",
4:{q:"Worin unterscheidet sich die Mandoline von der Geige?",o:["In der Stimmung","Darin, dass sie Bünde hat","In der Zahl der Saiten","Nur in der Größe"],w:"Die Stimmung ist identisch; der Unterschied sind die Bünde, und gerade sie erleichtern den Anfang."},
5:"Schlage jede leere Saite achtmal an, abwärts und aufwärts."}},

"mandolin-2":{title:"Erste Töne auf dem Hals",goal:"Deine erste Tonleiter spielen",b:{
0:"Dank der Bünde ist das Finden eines Tons auf der Mandoline eine Sache des Zählens — nicht des Hörens.",
2:"Fünf Töne",
3:"Ein Finger pro Bund — das ist die Regel, die dir Jahre an Korrekturen erspart.",
4:{q:"Wie findet man einen Ton auf der Mandoline?",o:["Nur nach Gehör","Über die Bundnummer","An der Farbe der Saite","Sicher gar nicht"],w:"Die Bünde legen die Tonhöhe genau fest."},
5:"Spiele die fünf Töne zehnmal auf und ab."}},

"mandolin-3":{title:"Eine erste Melodie",goal:"Ein ganzes Stück spielen",b:{
0:"Jetzt fügt sich alles zusammen: leere Saiten, Töne auf dem Hals und ein gleichmäßiger Anschlag.",
2:"Melodie für Mandoline",
3:"<b>Tremolo:</b> schnelles, wiederholtes Anschlagen desselben Tons. Das ist der Klang, den alle sofort als Mandoline erkennen — aber erst, wenn der normale Anschlag stabil ist.",
4:{q:"Was ist Tremolo?",o:["Ein schneller Akkordwechsel","Schnelles wiederholtes Anschlagen desselben Tons","Spiel auf zwei Saiten","Langsamer werden am Schluss"],w:"Es ist die charakteristische Technik der Mandoline."},
5:"Spiele die Melodie fünfmal mit gleichmäßigem Anschlag."}},

"mandolin-4":{title:"Dein erster Akkord",goal:"Einen G-Akkord spielen und darauf wechseln",b:{
0:"Auf der Mandoline besteht ein Akkord meist aus <b>nur zwei Fingern</b> — weit weniger, als eine Gitarre verlangt.",
2:["Finger 1 auf die A-Saite, 2. Bund.","Finger 2 auf die E-Saite, 3. Bund.","Die beiden übrigen Saiten bleiben leer.","Schlage abwärts über alle vier Paare."],
3:"Drücke direkt hinter dem Bund, nicht darauf. Dort braucht es die geringste Kraft.",
4:{q:"Wie viele Finger braucht ein einfacher Mandolinen-Akkord?",o:["Vier","Zwei","Drei","Keinen"],w:"Für die meisten offenen Akkorde genügen zwei."},
5:"Wechsle zwanzigmal zwischen G-Akkord und leeren Saiten."}},

"mandolin-5":{title:"Zwei Akkorde und ein Lied",goal:"Ein ganzes Lied mit zwei Akkorden begleiten",b:{
0:"Mit zwei Akkorden lassen sich bereits Hunderte von Liedern begleiten. Der Wechsel zwischen ihnen ist die ganze Übung.",
1:"Ab- und Aufschlag",
2:"<b>Die Regel des Wechsels:</b> Hebe die Finger einen Moment vor der Zählzeit, nicht auf ihr. So entsteht kein Loch im Rhythmus.",
3:"Begleitübung",
4:{q:"Wann hebt man beim Akkordwechsel die Finger?",o:["Genau auf der Zählzeit","Einen Moment vor der Zählzeit","Nach der Zählzeit","Das ist egal"],w:"Frühes Abheben erhält den durchgehenden Rhythmus."},
5:"Wechsle zwei Minuten lang ohne Pause zwischen den beiden Akkorden."}},

"mandolin-6":{title:"Tremolo",goal:"Mit wiederholtem Anschlag einen getragenen Ton erzeugen",b:{
0:"Die Mandoline hat keinen langen Ton — er verklingt sofort. Das <b>Tremolo</b> ist die Lösung: schnelles wiederholtes Anschlagen erzeugt die Illusion eines getragenen Tons.",
1:["Halte das Plektrum sehr locker — das ist entscheidend.","Bewege dich aus dem Handgelenk, nicht aus dem Ellbogen.","Beginne langsam und gleichmäßig, und werde erst dann schneller.","Spiele einen Ton vier Sekunden lang im Tremolo."],
2:"Ein verkrampfter Griff ergibt ein holpriges Tremolo. Je weicher der Griff, desto glatter der Klang.",
3:"Langer Ton im Tremolo",
4:{q:"Worauf kommt es beim Tremolo am meisten an?",o:["Auf Tempo","Auf einen lockeren Griff","Auf starken Druck","Auf ein dickes Plektrum"],w:"Lockerheit ermöglicht das Tempo; Anspannung verhindert es."},
5:"Übe Tremolo auf einem einzelnen Ton, eine Minute pro Saite."}},

"mandolin-7":{title:"Tonleitern über zwei Oktaven",goal:"Den Umfang auf dem Hals erweitern",b:{
0:"Dank der Quintenstimmung wiederholt sich dasselbe Fingermuster auf jedem Saitenpaar. Einmal gelernt — überall spielbar.",
2:"G-Tonleiter über zwei Oktaven",
3:"Das auf der G-Saite gelernte Muster funktioniert auf der D-Saite genau gleich. Das ist die große Ersparnis der Quintenstimmung.",
4:{q:"Was ist der Vorteil einer Quintenstimmung?",o:["Lauterer Klang","Dasselbe Muster wiederholt sich auf jedem Saitenpaar","Leichter zu stimmen","Weniger Saiten"],w:"Das Muster bleibt erhalten, man lernt es also nur ein einziges Mal."},
5:"Spiele die Tonleiter zehnmal über zwei Oktaven."}},

"mandolin-8":{title:"Melodie mit Begleitung",goal:"Ein ganzes Lied spielen und Akkorde einweben",b:{
0:"Jetzt kommt alles zusammen: Melodie, Akkorde und Tremolo in einem Stück.",
1:"Kombiniertes Stück",
2:"Spiele zuerst nur die Melodie, dann nur die Akkorde, und verbinde beides erst danach. Zu frühes Verbinden verdirbt beides.",
3:{q:"Wie verbindet man Melodie und Begleitung?",o:["Von Anfang an zusammen spielen","Jedes für sich lernen und dann verbinden","Auf eines von beiden verzichten","Sehr langsam spielen"],w:"Erst trennen, dann verbinden — das ist der schnelle Weg."},
4:"Spiele das kombinierte Stück fünfmal."}},

"mandolin-9":{title:"Rückblick und Ausblick",goal:"Wissen, was du gelernt hast und wie es weitergeht",b:{
0:"Du hast geschafft: leere Saiten, Töne auf dem Hals, Akkorde, Tremolo und Tonleitern über zwei Oktaven.",
1:"Wie es weitergeht: <b>Bluegrass-Stil</b> (schneller, präziser Anschlag), <b>geschlossene Akkorde</b>, die sich auf dem Hals verschieben, und <b>Improvisation</b> über die gelernten Tonleitern.",
2:"Abschlussstück",
3:"Die Mandoline teilt ihre Stimmung mit der Geige — alles hier Gelernte überträgt sich fast vollständig, falls du sie einmal ausprobieren willst.",
4:{q:"Welches Instrument teilt die Stimmung der Mandoline?",o:["Gitarre","Geige","Bass","Ukulele"],w:"Beide sind G-D-A-E gestimmt."},
5:"Spiele das Abschlussstück und nimm dich auf."}}

});
